window.TXB=window.TXB||{};TXB["svd/Num"]={"1:1":"وقال الرب لموسى في برية سيناء في خيمة الاجتماع في أول الشهر الثاني في السنة الثانية لخروجهم من أرض مصر:","1:2":"«أحصوا كل جماعة بني إسرائيل بعشائرهم وبيوت آبائهم بعدد الأسماء كل ذكر برأسه","1:3":"من ابن عشرين سنة فصاعدا كل خارج للحرب في إسرائيل. تحسبهم أنت وهارون حسب أجنادهم.","1:4":"ويكون معكما رجل لكل سبط هو رأس لبيت آبائه.","1:5":"وهذه أسماء الرجال الذين يقفون معكما. لرأوبين أليصور بن شديئور.","1:6":"لشمعون شلوميئيل بن صوريشداي.","1:7":"ليهوذا نحشون بن عميناداب.","1:8":"ليساكر نثنائيل بن صوغر.","1:9":"لزبولون أليآب بن حيلون.","1:10":"لابني يوسف: لأفرايم أليشمع بن عميهود ولمنسى جمليئيل بن فدهصور.","1:11":"لبنيامين أبيدن بن جدعوني.","1:12":"لدان أخيعزر بن عميشداي.","1:13":"لأشير فجعيئيل بن عكرن.","1:14":"لجاد ألياساف بن دعوئيل.","1:15":"لنفتالي أخيرع بن عينن».","1:16":"هؤلاء هم مشاهير الجماعة رؤساء أسباط آبائهم. رؤوس ألوف إسرائيل.","1:17":"فأخذ موسى وهارون هؤلاء الرجال الذين تعينوا بأسمائهم","1:18":"وجمعا كل الجماعة في أول الشهر الثاني فانتسبوا إلى عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا برؤوسهم","1:19":"كما أمر الرب موسى. فعدهم في برية سيناء.","1:20":"فكان بنو رأوبين بكر إسرائيل تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء برؤوسهم كل ذكر من ابن عشرين سنة فصاعدا كل خارج للحرب","1:21":"كان المعدودون منهم لسبط رأوبين ستة وأربعين ألفا وخمس مئة.","1:22":"بنو شمعون تواليدهم حسب عشائرهم وبيوت آبائهم المعدودون منهم بعدد الأسماء برؤوسهم كل ذكر من ابن عشرين سنة فصاعدا كل خارج للحرب","1:23":"المعدودون منهم لسبط شمعون تسعة وخمسون ألفا وثلاث مئة.","1:24":"بنو جاد تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:25":"المعدودون منهم لسبط جاد خمسة وأربعون ألفا وست مئة وخمسون.","1:26":"بنو يهوذا تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:27":"المعدودون منهم لسبط يهوذا أربعة وسبعون ألفا وست مئة.","1:28":"بنو يساكر تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:29":"المعدودون منهم لسبط يساكر أربعة وخمسون ألفا وأربع مئة.","1:30":"بنو زبولون تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:31":"المعدودون منهم لسبط زبولون سبعة وخمسون ألفا وأربع مئة.","1:32":"بنو يوسف: بنو أفرايم تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:33":"المعدودون منهم لسبط أفرايم أربعون ألفا وخمس مئة.","1:34":"بنو منسى تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:35":"المعدودون منهم لسبط منسى اثنان وثلاثون ألفا ومئتان.","1:36":"بنو بنيامين تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:37":"المعدودون منهم لسبط بنيامين خمسة وثلاثون ألفا وأربع مئة.","1:38":"بنو دان تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:39":"المعدودون منهم لسبط دان اثنان وستون ألفا وسبع مئة.","1:40":"بنو أشير تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:41":"المعدودون منهم لسبط أشير واحد وأربعون ألفا وخمس مئة.","1:42":"بنو نفتالي تواليدهم حسب عشائرهم وبيوت آبائهم بعدد الأسماء من ابن عشرين سنة فصاعدا كل خارج للحرب","1:43":"المعدودون منهم لسبط نفتالي ثلاثة وخمسون ألفا وأربع مئة.","1:44":"هؤلاء هم المعدودون الذين عدهم موسى وهارون ورؤساء إسرائيل اثنا عشر رجلا رجل واحد لبيت آبائه.","1:45":"فكان جميع المعدودين من بني إسرائيل حسب بيوت آبائهم من ابن عشرين سنة فصاعدا كل خارج للحرب في إسرائيل","1:46":"ست مئة ألف وثلاثة آلاف وخمس مئة وخمسين.","1:47":"وأما اللاويون حسب سبط آبائهم فلم يعدوا بينهم","1:48":"إذ قال الرب لموسى:","1:49":"«أما سبط لاوي فلا تحسبه ولا تعده بين بني إسرائيل.","1:50":"بل وكل اللاويين على مسكن الشهادة وعلى جميع أمتعته وعلى كل ما له. هم يحملون المسكن وكل أمتعته وهم يخدمونه وحول المسكن ينزلون.","1:51":"فعند ارتحال المسكن ينزله اللاويون وعند نزول المسكن يقيمه اللاويون. والأجنبي الذي يقترب يقتل.","1:52":"وينزل بنو إسرائيل كل في محلته وكل عند رايته بأجنادهم.","1:53":"وأما اللاويون فينزلون حول مسكن الشهادة لكي لا يكون سخط على جماعة بني إسرائيل فيحفظ اللاويون شعائر مسكن الشهادة».","1:54":"ففعل بنو إسرائيل حسب كل ما أمر الرب موسى.","2:1":"وقال الرب لموسى وهارون:","2:2":"«ينزل بنو إسرائيل كل عند رايته بأعلام لبيوت آبائهم. قبالة خيمة الاجتماع حولها ينزلون.","2:3":"فالنازلون إلى الشرق نحو الشروق راية محلة يهوذا حسب أجنادهم. والرئيس لبني يهوذا نحشون بن عميناداب.","2:4":"وجنده المعدودون منهم أربعة وسبعون ألفا وست مئة.","2:5":"والنازلون معه سبط يساكر. والرئيس لبني يساكر نثنائيل بن صوغر.","2:6":"وجنده المعدودون منه أربعة وخمسون ألفا وأربع مئة.","2:7":"وسبط زبولون. والرئيس لبني زبولون أليآب بن حيلون.","2:8":"وجنده المعدودون منه سبعة وخمسون ألفا وأربع مئة.","2:9":"جميع المعدودين لمحلة يهوذا مئة ألف وستة وثمانون ألفا وأربع مئة بأجنادهم. يرتحلون أولا.","2:10":"«راية محلة رأوبين إلى التيمن حسب أجنادهم. والرئيس لبني رأوبين أليصور بن شديئور","2:11":"وجنده المعدودون منه ستة وأربعون ألفا وخمس مئة.","2:12":"والنازلون معه سبط شمعون. والرئيس لبني شمعون شلوميئيل بن صوريشداي.","2:13":"وجنده المعدودون منهم تسعة وخمسون ألفا وثلاث مئة.","2:14":"وسبط جاد. والرئيس لبني جاد ألياساف بن رعوئيل.","2:15":"وجنده المعدودون منهم خمسة وأربعون ألفا وست مئة وخمسون.","2:16":"جميع المعدودين لمحلة رأوبين مئة ألف وواحد وخمسون ألفا وأربع مئة وخمسون بأجنادهم ويرتحلون ثانية.","2:17":"«ثم ترتحل خيمة الاجتماع. محلة اللاويين في وسط المحلات. كما ينزلون كذلك يرتحلون. كل في موضعه براياتهم.","2:18":"«راية محلة أفرايم حسب أجنادهم إلى الغرب. والرئيس لبني أفرايم أليشمع بن عميهود.","2:19":"وجنده المعدودون منهم أربعون ألفا وخمس مئة.","2:20":"ومعه سبط منسى. والرئيس لبني منسى جمليئيل بن فدهصور.","2:21":"وجنده المعدودون منهم اثنان وثلاثون ألفا ومئتان.","2:22":"وسبط بنيامين. والرئيس لبني بنيامين أبيدن بن جدعوني.","2:23":"وجنده المعدودون منهم خمسة وثلاثون ألفا وأربع مئة.","2:24":"جميع المعدودين لمحلة أفرايم مئة ألف وثمانية آلاف ومئة بأجنادهم. ويرتحلون ثالثة.","2:25":"«راية محلة دان إلى الشمال حسب أجنادهم. والرئيس لبني دان أخيعزر بن عميشداي.","2:26":"وجنده المعدودون منهم اثنان وستون ألفا وسبع مئة.","2:27":"والنازلون معه سبط أشير. والرئيس لبني أشير فجعيئيل بن عكرن.","2:28":"وجنده المعدودون منهم واحد وأربعون ألفا وخمس مئة.","2:29":"وسبط نفتالي. والرئيس لبني نفتالي أخيرع بن عينن.","2:30":"وجنده المعدودون منهم ثلاثة وخمسون ألفا وأربع مئة.","2:31":"جميع المعدودين لمحلة دان مئة ألف وسبعة وخمسون ألفا وست مئة. يرتحلون أخيرا براياتهم».","2:32":"هؤلاء هم المعدودون من بني إسرائيل حسب بيوت آبائهم. جميع المعدودين من المحلات بأجنادهم ست مئة ألف وثلاثة آلاف وخمس مئة وخمسون.","2:33":"وأما اللاويون فلم يعدوا بين بني إسرائيل كما أمر الرب موسى.","2:34":"ففعل بنو إسرائيل حسب كل ما أمر به الرب موسى. هكذا نزلوا براياتهم وهكذا ارتحلوا. كل حسب عشائره مع بيت آبائه.","3:1":"وهذه تواليد هارون وموسى يوم كلم الرب موسى في جبل سيناء.","3:2":"وهذه أسماء بني هارون: ناداب البكر وأبيهو وألعازار وإيثامار.","3:3":"هذه أسماء بني هارون الكهنة الممسوحين الذين ملأ أيديهم للكهانة.","3:4":"ولكن مات ناداب وأبيهو أمام الرب عندما قربا نارا غريبة أمام الرب في برية سيناء ولم يكن لهما بنون. وأما ألعازار وإيثامار فكهنا أمام هارون أبيهما.","3:5":"وقال الرب لموسى:","3:6":"«قدم سبط لاوي وأوقفهم قدام هارون الكاهن وليخدموه.","3:7":"فيحفظون شعائره وشعائر كل الجماعة قدام خيمة الاجتماع ويخدمون خدمة المسكن","3:8":"فيحرسون كل أمتعة خيمة الاجتماع وحراسة بني إسرائيل ويخدمون خدمة المسكن.","3:9":"فتعطي اللاويين لهارون ولبنيه. إنهم موهوبون له هبة من عند بني إسرائيل.","3:10":"وتوكل هارون وبنيه فيحرسون كهنوتهم. والأجنبي الذي يقترب يقتل».","3:11":"وقال الرب لموسى:","3:12":"«وها إني قد أخذت اللاويين من بين بني إسرائيل بدل كل بكر فاتح رحم من بني إسرائيل فيكون اللاويون لي.","3:13":"لأن لي كل بكر. يوم ضربت كل بكر في أرض مصر قدست لي كل بكر في إسرائيل من الناس والبهائم. لي يكونون. أنا الرب».","3:14":"وأمر الرب موسى في برية سيناء:","3:15":"«عد بني لاوي حسب بيوت آبائهم وعشائرهم. كل ذكر من ابن شهر فصاعدا تعدهم».","3:16":"فعدهم موسى حسب قول الرب كما أمر.","3:17":"وكان هؤلاء بني لاوي بأسمائهم: جرشون وقهات ومراري.","3:18":"وهذان اسما ابني جرشون حسب عشائرهما: لبني وشمعي.","3:19":"وبنو قهات حسب عشائرهم: عمرام ويصهار وحبرون وعزيئيل.","3:20":"وابنا مراري حسب عشائرهما: محلي وموشي. هذه هي عشائر اللاويين حسب بيوت آبائهم.","3:21":"لجرشون عشيرة اللبنيين وعشيرة الشمعيين. هذه هي عشائر الجرشونيين.","3:22":"المعدودون منهم بعدد كل ذكر من ابن شهر فصاعدا المعدودون منهم سبعة آلاف وخمس مئة.","3:23":"عشائر الجرشونيين ينزلون وراء المسكن إلى الغرب.","3:24":"والرئيس لبيت أبي الجرشونيين ألياساف بن لايل.","3:25":"وحراسة بني جرشون في خيمة الاجتماع: المسكن والخيمة وغطاؤها وسجف باب خيمة الاجتماع","3:26":"وأستار الدار وسجف باب الدار اللواتي حول المسكن وحول المذبح محيطا وأطنابه مع كل خدمته.","3:27":"ولقهات عشيرة العمراميين وعشيرة اليصهاريين وعشيرة الحبرونيين وعشيرة العزيئيليين. هذه عشائر القهاتيين","3:28":"بعدد كل ذكر من ابن شهر فصاعدا ثمانية آلاف وست مئة حارسين حراسة القدس.","3:29":"وعشائر بني قهات ينزلون على جانب المسكن إلى التيمن.","3:30":"والرئيس لبيت أبي عشيرة القهاتيين أليصافان بن عزيئيل.","3:31":"وحراستهم التابوت والمائدة والمنارة والمذبحان وأمتعة القدس التي يخدمون بها والحجاب وكل خدمته.","3:32":"ولرئيس رؤساء اللاويين ألعازار بن هارون الكاهن وكالة حراس حراسة القدس.","3:33":"ولمراري عشيرة المحليين وعشيرة الموشيين. هذه هي عشائر مراري.","3:34":"والمعدودون منهم بعدد كل ذكر من ابن شهر فصاعدا ستة آلاف ومئتان.","3:35":"والرئيس لبيت أبي عشائر مراري صوريئيل بن أبيجايل. ينزلون على جانب المسكن إلى الشمال.","3:36":"ووكالة حراسة بني مراري ألواح المسكن وعوارضه وأعمدته وفرضه وكل أمتعته وكل خدمته","3:37":"وأعمدة الدار حواليها وفرضها وأوتادها وأطنابها.","3:38":"والنازلون قدام المسكن إلى الشرق قدام خيمة الاجتماع نحو الشروق هم موسى وهارون وبنوه حارسين حراسة المقدس لحراسة بني إسرائيل. والأجنبي الذي يقترب يقتل.","3:39":"جميع المعدودين من اللاويين الذين عدهم موسى وهارون حسب قول الرب بعشائرهم كل ذكر من ابن شهر فصاعدا اثنان وعشرون ألفا.","3:40":"وقال الرب لموسى: «عد كل بكر ذكر من بني إسرائيل من ابن شهر فصاعدا وخذ عدد أسمائهم.","3:41":"فتأخذ اللاويين لي. أنا الرب. بدل كل بكر في بني إسرائيل. وبهائم اللاويين بدل كل بكر في بهائم بني إسرائيل».","3:42":"فعد موسى كما أمره الرب كل بكر في بني إسرائيل.","3:43":"فكان جميع الأبكار الذكور بعدد الأسماء من ابن شهر فصاعدا المعدودين منهم اثنين وعشرين ألفا ومئتين وثلاثة وسبعين.","3:44":"وقال الرب لموسى:","3:45":"«خذ اللاويين بدل كل بكر في بني إسرائيل وبهائم اللاويين بدل بهائمهم فيكون لي اللاويون. أنا الرب.","3:46":"وأما فداء المئتين والثلاثة والسبعين الزائدين على اللاويين من أبكار بني إسرائيل","3:47":"فتأخذ خمسة شواقل لكل رأس. على شاقل القدس تأخذها. عشرون جيرة الشاقل.","3:48":"وتعطي الفضة لهارون وبنيه فداء الزائدين عليهم».","3:49":"فأخذ موسى فضة فدائهم من الزائدين على فداء اللاويين.","3:50":"من أبكار بني إسرائيل أخذ الفضة ألفا وثلاث مئة وخمسة وستين على شاقل القدس","3:51":"وأعطى موسى فضة الفداء لهارون وبنيه حسب قول الرب كما أمر الرب موسى.","4:1":"وقال الرب لموسى وهارون:","4:2":"«خذ عدد بني قهات من بين بني لاوي حسب عشائرهم وبيوت آبائهم","4:3":"من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة كل داخل في الجند ليعمل عملا في خيمة الاجتماع.","4:4":"هذه خدمة بني قهات في خيمة الاجتماع: قدس الأقداس.","4:5":"يأتي هارون وبنوه عند ارتحال المحلة وينزلون حجاب السجف ويغطون به تابوت الشهادة","4:6":"ويجعلون عليه غطاء من جلد تخس ويبسطون من فوق ثوبا كله أسمانجوني ويضعون عصيه.","4:7":"وعلى مائدة الوجوه يبسطون ثوب أسمانجون ويضعون عليه الصحاف والصحون والأقداح وكاسات السكيب. ويكون الخبز الدائم عليه.","4:8":"ويبسطون عليها ثوب قرمز ويغطونه بغطاء من جلد تخس ويضعون عصيه.","4:9":"ويأخذون ثوب أسمانجون ويغطون منارة الضوء وسرجها وملاقطها ومنافضها وجميع آنية زيتها التي يخدمونها بها.","4:10":"ويجعلونها وجميع آنيتها في غطاء من جلد تخس ويجعلونه على العتلة.","4:11":"وعلى مذبح الذهب يبسطون ثوب أسمانجون ويغطونه بغطاء من جلد تخس ويضعون عصيه.","4:12":"ويأخذون جميع أمتعة الخدمة التي يخدمون بها في القدس ويجعلونها في ثوب أسمانجون ويغطونها بغطاء من جلد تخس ويجعلونها على العتلة.","4:13":"ويرفعون رماد المذبح ويبسطون عليه ثوب أرجوان.","4:14":"ويجعلون عليه جميع أمتعته التي يخدمون عليه بها المجامر والمناشل والرفوش والمناضح كل أمتعة المذبح. ويبسطون عليه غطاء من جلد تخس ويضعون عصيه.","4:15":"ومتى فرغ هارون وبنوه من تغطية القدس وجميع أمتعة القدس عند ارتحال المحلة يأتي بعد ذلك بنو قهات للحمل ولكن لا يمسوا القدس لئلا يموتوا. ذلك حمل بني قهات في خيمة الاجتماع.","4:16":"ووكالة ألعازار بن هارون الكاهن هي زيت الضوء والبخور العطر والتقدمة الدائمة ودهن المسحة ووكالة كل المسكن وكل ما فيه بالقدس وأمتعته».","4:17":"وأمر الرب موسى وهارون:","4:18":"«لا تقرضا سبط عشائر القهاتيين من بين اللاويين.","4:19":"بل افعلا لهم هذا فيعيشوا ولا يموتوا عند اقترابهم إلى قدس الأقداس. يدخل هارون وبنوه ويقيمونهم كل إنسان على خدمته وحمله","4:20":"ولا يدخلوا ليروا القدس لحظة لئلا يموتوا».","4:21":"وأمر الرب موسى:","4:22":"«خذ عدد بني جرشون أيضا حسب بيوت آبائهم وعشائرهم","4:23":"من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة تعدهم. كل الداخلين ليتجندوا أجنادا ليخدموا خدمة في خيمة الاجتماع.","4:24":"هذه خدمة عشائر الجرشونيين من الخدمة والحمل:","4:25":"يحملون شقق المسكن وخيمة الاجتماع وغطاءها وغطاء التخس الذي عليها من فوق وسجف باب خيمة الاجتماع","4:26":"وأستار الدار وسجف مدخل باب الدار اللواتي حول المسكن وحول المذبح محيطة وأطنابهن وكل أمتعة خدمتهن. وكل ما يعمل لهن فهم يصنعونه","4:27":"حسب قول هارون وبنيه تكون جميع خدمة بني الجرشونيين من كل حملهم ومن كل خدمتهم. وتوكلهم بحراسة كل أحمالهم.","4:28":"هذه خدمة عشائر بني الجرشونيين في خيمة الاجتماع وحراستهم بيد إيثامار بن هارون الكاهن.","4:29":"«بنو مراري حسب عشائرهم وبيوت آبائهم تعدهم.","4:30":"من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة تعدهم كل الداخلين في الجند ليخدموا خدمة خيمة الاجتماع.","4:31":"وهذه حراسة حملهم وكل خدمتهم في خيمة الاجتماع: ألواح المسكن وعوارضه وأعمدته وفرضه","4:32":"وأعمدة الدار حواليها وفرضها وأوتادها وأطنابها مع كل أمتعتها وكل خدمتها. وبالأسماء تعدون أمتعة حراسة حملهم.","4:33":"هذه خدمة عشائر بني مراري. كل خدمتهم في خيمة الاجتماع بيد إيثامار بن هارون الكاهن».","4:34":"فعد موسى وهارون ورؤساء الجماعة بني القهاتيين حسب عشائرهم وبيوت آبائهم","4:35":"من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة كل الداخلين في الجند للخدمة في خيمة الاجتماع.","4:36":"فكان المعدودون منهم حسب عشائرهم ألفين وسبع مئة وخمسين.","4:37":"هؤلاء هم المعدودون من عشائر القهاتيين كل الخادمين في خيمة الاجتماع الذين عدهم موسى وهارون حسب قول الرب عن يد موسى.","4:38":"والمعدودون من بني جرشون حسب عشائرهم وبيوت آبائهم","4:39":"من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة كل الداخلين في الجند للخدمة في خيمة الاجتماع","4:40":"كان المعدودون منهم حسب عشائرهم وبيوت آبائهم ألفين وست مئة وثلاثين.","4:41":"هؤلاء هم المعدودون من عشائر بني جرشون كل الخادمين في خيمة الاجتماع الذين عدهم موسى وهارون حسب قول الرب.","4:42":"والمعدودون من عشائر بني مراري حسب عشائرهم وبيوت آبائهم","4:43":"من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة كل الداخلين في الجند للخدمة في خيمة الاجتماع","4:44":"كان المعدودون منهم حسب عشائرهم ثلاثة آلاف ومئتين.","4:45":"هؤلاء هم المعدودون من عشائر بني مراري الذين عدهم موسى وهارون حسب قول الرب عن يد موسى.","4:46":"جميع المعدودين اللاويين الذين عدهم موسى وهارون ورؤساء إسرائيل حسب عشائرهم وبيوت آبائهم","4:47":"من ابن ثلاثين سنة فصاعدا إلى ابن خمسين سنة كل الداخلين ليعملوا عمل الخدمة وعمل الحمل في خيمة الاجتماع","4:48":"كان المعدودون منهم ثمانية آلاف وخمس مئة وثمانين.","4:49":"حسب قول الرب عن يد موسى عد كل إنسان على خدمته وعلى حمله الذين عدهم موسى كما أمره الرب.","5:1":"وأمر الرب موسى:","5:2":"«أوص بني إسرائيل أن ينفوا من المحلة كل أبرص وكل ذي سيل وكل متنجس لميت.","5:3":"الذكر والأنثى تنفون. إلى خارج المحلة تنفونهم لكيلا ينجسوا محلاتهم حيث أنا ساكن في وسطهم».","5:4":"ففعل هكذا بنو إسرائيل ونفوهم إلى خارج المحلة. كما كلم الرب موسى هكذا فعل بنو إسرائيل.","5:5":"وأمر الرب موسى:","5:6":"«قل لبني إسرائيل: إذا عمل رجل أو امرأة شيئا من جميع خطايا الإنسان وخان خيانة بالرب فقد أذنبت تلك النفس.","5:7":"فلتقر بخطيتها التي عملت وترد ما أذنبت به بعينه وتزد عليه خمسه وتدفعه للذي أذنبت إليه.","5:8":"وإن كان ليس للرجل ولي ليرد إليه المذنب به فالمذنب به المردود يكون للرب لأجل الكاهن فضلا عن كبش الكفارة الذي يكفر به عنه.","5:9":"وكل رفيعة مع كل أقداس بني إسرائيل التي يقدمونها للكاهن تكون له.","5:10":"والإنسان أقداسه تكون له. إذا أعطى إنسان شيئا للكاهن فله يكون».","5:11":"وأمر الرب موسى:","5:12":"«قل لبني إسرائيل: إذا زاغت امرأة رجل وخانته خيانة","5:13":"واضطجع معها رجل اضطجاع زرع وأخفي ذلك عن عيني رجلها واستترت وهي نجسة وليس شاهد عليها وهي لم تؤخذ","5:14":"فاعتراه روح الغيرة وغار على امرأته وهي نجسة أو اعتراه روح الغيرة وغار على امرأته وهي ليست نجسة","5:15":"يأتي الرجل بامرأته إلى الكاهن ويأتي بقربانها معها: عشر الإيفة من طحين شعير لا يصب عليه زيتا ولا يجعل عليه لبانا لأنه تقدمة غيرة تقدمة تذكار تذكر ذنبا.","5:16":"فيقدمها الكاهن ويوقفها أمام الرب","5:17":"ويأخذ الكاهن ماء مقدسا في إناء خزف ويأخذ الكاهن من الغبار الذي في أرض المسكن ويجعل في الماء","5:18":"ويوقف الكاهن المرأة أمام الرب ويكشف رأس المرأة ويجعل في يديها تقدمة التذكار التي هي تقدمة الغيرة وفي يد الكاهن يكون ماء اللعنة المر.","5:19":"ويستحلف الكاهن المرأة ويقول لها: إن كان لم يضطجع معك رجل وإن كنت لم تزيغي إلى نجاسة من تحت رجلك فكوني بريئة من ماء اللعنة هذا المر.","5:20":"ولكن إن كنت قد زغت من تحت رجلك وتنجست وجعل معك رجل غير رجلك مضجعه.","5:21":"يستحلف الكاهن المرأة بحلف اللعنة ويقول الكاهن للمرأة: يجعلك الرب لعنة وحلفا بين شعبك بأن يجعل الرب فخذك ساقطة وبطنك وارما.","5:22":"ويدخل ماء اللعنة هذا في أحشائك لورم البطن ولإسقاط الفخذ. فتقول المرأة: آمين آمين.","5:23":"ويكتب الكاهن هذه اللعنات في الكتاب ثم يمحوها في الماء المر","5:24":"ويسقي المرأة ماء اللعنة المر فيدخل فيها ماء اللعنة للمرارة.","5:25":"ويأخذ الكاهن من يد المرأة تقدمة الغيرة ويردد التقدمة أمام الرب ويقدمها إلى المذبح.","5:26":"ويقبض الكاهن من التقدمة تذكارها ويوقده على المذبح وبعد ذلك يسقي المرأة الماء.","5:27":"ومتى سقاها الماء فإن كانت قد تنجست وخانت رجلها يدخل فيها ماء اللعنة للمرارة فيرم بطنها وتسقط فخذها فتصير المرأة لعنة في وسط شعبها.","5:28":"وإن لم تكن المرأة قد تنجست بل كانت طاهرة تتبرأ وتحبل بزرع».","5:29":"هذه شريعة الغيرة. إذا زاغت امرأة من تحت رجلها وتنجست","5:30":"أو إذا اعترى رجلا روح غيرة فغار على امرأته يوقف المرأة أمام الرب ويعمل لها الكاهن كل هذه الشريعة","5:31":"فيتبرأ الرجل من الذنب وتلك المرأة تحمل ذنبها.","6:1":"وأمر الرب موسى:","6:2":"«قل لبني إسرائيل: إذا انفرز رجل أو امرأة لينذر نذر النذير لينتذر للرب","6:3":"فعن الخمر والمسكر يفترز ولا يشرب خل الخمر ولا خل المسكر ولا يشرب من نقيع العنب ولا يأكل عنبا رطبا ولا يابسا.","6:4":"كل أيام نذره لا يأكل من كل ما يعمل من جفنة الخمر من العجم حتى القشر.","6:5":"كل أيام نذر افترازه لا يمر موسى على رأسه. إلى كمال الأيام التي انتذر فيها للرب يكون مقدسا ويربي خصل شعر رأسه.","6:6":"كل أيام انتذاره للرب لا يأتي إلى جسد ميت.","6:7":"أبوه وأمه وأخوه وأخته لا يتنجس من أجلهم عند موتهم لأن انتذار إلهه على رأسه.","6:8":"إنه كل أيام انتذاره مقدس للرب.","6:9":"وإذا مات ميت عنده بغتة على فجأة فنجس رأس انتذاره يحلق رأسه يوم طهره. في اليوم السابع يحلقه.","6:10":"وفي اليوم الثامن يأتي بيمامتين أو بفرخي حمام إلى الكاهن إلى باب خيمة الاجتماع","6:11":"فيعمل الكاهن واحدا ذبيحة خطية والآخر محرقة ويكفر عنه ما أخطأ بسبب الميت ويقدس رأسه في ذلك اليوم.","6:12":"فمتى نذر للرب أيام انتذاره يأتي بخروف حولي ذبيحة إثم وأما الأيام الأولى فتسقط لأنه نجس انتذاره.","6:13":"«وهذه شريعة النذير: يوم تكمل أيام انتذاره يؤتى به إلى باب خيمة الاجتماع","6:14":"فيقرب قربانه للرب خروفا واحدا حوليا صحيحا محرقة ونعجة واحدة حولية صحيحة ذبيحة خطية وكبشا واحدا صحيحا ذبيحة سلامة","6:15":"وسل فطير من دقيق أقراصا ملتوتة بزيت ورقاق فطير مدهونة بزيت مع تقدمتها وسكائبها","6:16":"فيقدمها الكاهن أمام الرب ويعمل ذبيحة خطيته ومحرقته.","6:17":"والكبش يعمله ذبيحة سلامة للرب مع سل الفطير ويعمل الكاهن تقدمته وسكيبه.","6:18":"ويحلق النذير لدى باب خيمة الاجتماع رأس انتذاره ويأخذ شعر رأس انتذاره ويجعله على النار التي تحت ذبيحة السلامة.","6:19":"ويأخذ الكاهن الساعد مسلوقا من الكبش وقرص فطير واحدا من السل ورقاقة فطير واحدة ويجعلها في يدي النذير بعد حلقه شعر انتذاره","6:20":"ويرددها الكاهن ترديدا أمام الرب. إنه قدس للكاهن مع صدر الترديد وساق الرفيعة. وبعد ذلك يشرب النذير خمرا.","6:21":"هذه شريعة النذير الذي ينذر. قربانه للرب عن انتذاره فضلا عما تنال يده. حسب نذره الذي نذر كذلك يعمل حسب شريعة انتذاره».","6:22":"وأمر الرب موسى:","6:23":"«قل لهارون وبنيه: هكذا تباركون بني إسرائيل:","6:24":"يباركك الرب ويحرسك.","6:25":"يضيء الرب بوجهه عليك ويرحمك.","6:26":"يرفع الرب وجهه عليك ويمنحك سلاما.","6:27":"فيجعلون اسمي على بني إسرائيل وأنا أباركهم».","7:1":"ويوم فرغ موسى من إقامة المسكن ومسحه وقدسه وجميع أمتعته والمذبح وجميع أمتعته ومسحها وقدسها","7:2":"قرب رؤساء إسرائيل رؤوس بيوت آبائهم هم رؤساء الأسباط الذين وقفوا على المعدودين.","7:3":"أتوا بقرابينهم أمام الرب: ست عجلات مغطاة واثني عشر ثورا. لكل رئيسين عجلة ولكل واحد ثور وقدموها أمام المسكن.","7:4":"فقال الرب لموسى:","7:5":"«خذها منهم فتكون لعمل خدمة خيمة الاجتماع وأعطها للاويين لكل واحد حسب خدمته».","7:6":"فأخذ موسى العجلات والثيران وأعطاها للاويين.","7:7":"اثنتان من العجلات وأربعة من الثيران أعطاها لبني جرشون حسب خدمتهم.","7:8":"وأربع من العجلات وثمانية من الثيران أعطاها لبني مراري حسب خدمتهم بيد إيثامار بن هارون الكاهن.","7:9":"وأما بنو قهات فلم يعطهم لأن خدمة القدس كانت عليهم. على الأكتاف كانوا يحملون.","7:10":"وقرب الرؤساء لتدشين المذبح يوم مسحه. وقدم الرؤساء قرابينهم أمام المذبح.","7:11":"فقال الرب لموسى: «رئيسا رئيسا في كل يوم يقربون قرابينهم لتدشين المذبح».","7:12":"والذي قرب قربانه في اليوم الأول نحشون بن عميناداب من سبط يهوذا.","7:13":"وقربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:14":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:15":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:16":"وتيس واحد من المعز لذبيحة خطية.","7:17":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان نحشون بن عميناداب.","7:18":"وفي اليوم الثاني قرب نثنائيل بن صوغر رئيس يساكر.","7:19":"قرب قربانه طبقا واحدا من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعين شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:20":"وصحنا واحدا عشرة شواقل من ذهب مملوا بخورا","7:21":"وثورا واحدا ابن بقر وكبشا واحدا وخروفا واحدا حوليا لمحرقة","7:22":"وتيسا واحدا من المعز لذبيحة خطية.","7:23":"ولذبيحة السلامة ثورين وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان نثنائيل بن صوغر.","7:24":"وفي اليوم الثالث رئيس بني زبولون أليآب بن حيلون.","7:25":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:26":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:27":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:28":"وتيس واحد من المعز لذبيحة خطية","7:29":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان أليآب بن حيلون.","7:30":"وفي اليوم الرابع رئيس بني رأوبين أليصور بن شديئور.","7:31":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:32":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:33":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:34":"وتيس واحد من المعز لذبيحة خطية.","7:35":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان أليصور بن شديئور.","7:36":"وفي اليوم الخامس رئيس بني شمعون شلوميئيل بن صوريشداي.","7:37":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:38":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:39":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:40":"وتيس واحد من المعز لذبيحة خطية.","7:41":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان شلوميئيل بن صوريشداي.","7:42":"وفي اليوم السادس رئيس بني جاد ألياساف بن دعوئيل.","7:43":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:44":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:45":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:46":"وتيس واحد من المعز لذبيحة خطية.","7:47":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان ألياساف بن دعوئيل.","7:48":"وفي اليوم السابع رئيس بني أفرايم أليشمع بن عميهود.","7:49":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:50":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:51":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:52":"وتيس واحد من المعز لذبيحة خطية","7:53":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان أليشمع بن عميهود.","7:54":"وفي اليوم الثامن رئيس بني منسى جمليئيل بن فدهصور.","7:55":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:56":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:57":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:58":"وتيس واحد من المعز لذبيحة خطية.","7:59":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان جمليئيل بن فدهصور.","7:60":"وفي اليوم التاسع رئيس بني بنيامين أبيدن بن جدعوني.","7:61":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:62":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:63":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:64":"وتيس واحد من المعز لذبيحة خطية","7:65":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان أبيدن بن جدعوني.","7:66":"وفي اليوم العاشر رئيس بني دان أخيعزر بن عميشداي.","7:67":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:68":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:69":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:70":"وتيس واحد من المعز لذبيحة خطية.","7:71":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان أخيعزر بن عميشداي.","7:72":"وفي اليوم الحادي عشر رئيس بني أشير فجعيئيل بن عكرن.","7:73":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:74":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:75":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:76":"وتيس واحد من المعز لذبيحة خطية.","7:77":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان فجعيئيل بن عكرن.","7:78":"وفي اليوم الثاني عشر رئيس بني نفتالي أخيرع بن عينن.","7:79":"قربانه طبق واحد من فضة وزنه مئة وثلاثون شاقلا ومنضحة واحدة من فضة سبعون شاقلا على شاقل القدس كلتاهما مملوءتان دقيقا ملتوتا بزيت لتقدمة","7:80":"وصحن واحد عشرة شواقل من ذهب مملوء بخورا","7:81":"وثور واحد ابن بقر وكبش واحد وخروف واحد حولي لمحرقة","7:82":"وتيس واحد من المعز لذبيحة خطية.","7:83":"ولذبيحة السلامة ثوران وخمسة كباش وخمسة تيوس وخمسة خراف حولية. هذا قربان أخيرع بن عينن.","7:84":"هذا تدشين المذبح يوم مسحه من رؤساء إسرائيل. أطباق فضة اثنا عشر ومناضح فضة اثنتا عشرة وصحون ذهب اثنا عشر","7:85":"كل طبق مئة وثلاثون شاقل فضة وكل منضحة سبعون. جميع فضة الآنية ألفان وأربع مئة على شاقل القدس.","7:86":"وصحون الذهب اثنا عشر مملوءة بخورا كل صحن عشرة على شاقل القدس. جميع ذهب الصحون مئة وعشرون شاقلا.","7:87":"كل الثيران للمحرقة اثنا عشر ثورا والكباش اثنا عشر والخراف الحولية اثنا عشر مع تقدمتها وتيوس المعز اثنا عشر لذبيحة الخطية.","7:88":"وكل الثيران لذبيحة السلامة أربعة وعشرون ثورا والكباش ستون والتيوس ستون والخراف الحولية ستون. هذا تدشين المذبح بعد مسحه.","7:89":"فلما دخل موسى إلى خيمة الاجتماع ليتكلم معه كان يسمع الصوت يكلمه من على الغطاء الذي على تابوت الشهادة من بين الكروبين فكلمه.","8:1":"وقال الرب لموسى:","8:2":"«قل لهارون: متى رفعت السرج فإلى قدام المنارة تضيء السرج السبعة».","8:3":"ففعل هارون هكذا. إلى قدام المنارة رفع سرجها كما أمر الرب موسى.","8:4":"وهذه هي صنعة المنارة: مسحولة من ذهب. حتى ساقها وزهرها هي مسحولة. حسب المنظر الذي أراه الرب موسى هكذا عمل المنارة.","8:5":"وقال الرب لموسى:","8:6":"«خذ اللاويين من بين بني إسرائيل وطهرهم","8:7":"وهكذا تفعل لهم لتطهيرهم: انضح عليهم ماء الخطية وليمروا موسى على كل جسدهم ويغسلوا ثيابهم فيتطهروا.","8:8":"ثم يأخذوا ثورا ابن بقر وتقدمته دقيقا ملتوتا بزيت. وثورا آخر ابن بقر تأخذ لذبيحة خطية.","8:9":"فتقدم اللاويين أمام خيمة الاجتماع وتجمع كل جماعة بني إسرائيل","8:10":"وتقدم اللاويين أمام الرب فيضع بنو إسرائيل أيديهم على اللاويين.","8:11":"ويردد هارون اللاويين ترديدا أمام الرب من عند بني إسرائيل فيكونون لخدمة الرب.","8:12":"ثم يضع اللاويون أيديهم على رأسي الثورين فتقرب الواحد ذبيحة خطية والآخر محرقة للرب للتكفير عن اللاويين.","8:13":"فتوقف اللاويين أمام هارون وبنيه وترددهم ترديدا للرب.","8:14":"وتفرز اللاويين من بين بني إسرائيل فيكون اللاويون لي.","8:15":"وبعد ذلك يأتي اللاويون ليخدموا خيمة الاجتماع فتطهرهم وترددهم ترديدا","8:16":"لأنهم موهوبون لي هبة من بين بني إسرائيل. بدل كل فاتح رحم بكر كل من إسرائيل قد اتخذتهم لي.","8:17":"لأن لي كل بكر في بني إسرائيل من الناس ومن البهائم. يوم ضربت كل بكر في أرض مصر قدستهم لي.","8:18":"فاتخذت اللاويين بدل كل بكر في بني إسرائيل.","8:19":"ووهبت اللاويين هبة لهارون وبنيه من بين بني إسرائيل ليخدموا خدمة بني إسرائيل في خيمة الاجتماع وللتكفير عن بني إسرائيل لكي لا يكون في بني إسرائيل وبأ عند اقتراب بني إسرائيل إلى القدس».","8:20":"ففعل موسى وهارون وكل جماعة بني إسرائيل للاويين حسب كل ما أمر الرب موسى عن اللاويين. هكذا فعل لهم بنو إسرائيل.","8:21":"فتطهر اللاويون وغسلوا ثيابهم ورددهم هارون ترديدا أمام الرب وكفر عنهم هارون لتطهيرهم.","8:22":"وبعد ذلك أتى اللاويون ليخدموا خدمتهم في خيمة الاجتماع أمام هارون وأمام بنيه - كما أمر الرب موسى عن اللاويين هكذا فعلوا لهم.","8:23":"وقال الرب لموسى:","8:24":"«هذا ما للاويين: من ابن خمس وعشرين سنة فصاعدا يأتون ليتجندوا أجنادا في خدمة خيمة الاجتماع.","8:25":"ومن ابن خمسين سنة يرجعون من جند الخدمة ولا يخدمون بعد.","8:26":"يوازرون إخوتهم في خيمة الاجتماع لحرس حراسة. لكن خدمة لا يخدمون. هكذا تعمل للاويين في حراساتهم».","9:1":"وقال الرب لموسى في برية سيناء في السنة الثانية لخروجهم من أرض مصر في الشهر الأول:","9:2":"«وليعمل بنو إسرائيل الفصح في وقته.","9:3":"في اليوم الرابع عشر من هذا الشهر بين العشاءين تعملونه في وقته. حسب كل فرائضه وكل أحكامه تعملونه».","9:4":"فكلم موسى بني إسرائيل أن يعملوا الفصح.","9:5":"فعملوا الفصح في الشهر الأول في اليوم الرابع عشر من الشهر بين العشاءين في برية سيناء - حسب كل ما أمر الرب موسى هكذا فعل بنو إسرائيل.","9:6":"لكن كان قوم قد تنجسوا لإنسان ميت فلم يحل لهم أن يعملوا الفصح في ذلك اليوم. فتقدموا أمام موسى وهارون في ذلك اليوم","9:7":"وقالوا له: «إننا متنجسون لإنسان ميت. لماذا نترك حتى لا نقرب قربان الرب في وقته بين بني إسرائيل؟»","9:8":"فقال لهم موسى: «قفوا لأسمع ما يأمر به الرب من جهتكم».","9:9":"فأمر الرب موسى:","9:10":"«قل لبني إسرائيل: كل إنسان منكم أو من أجيالكم كان نجسا لميت أو في سفر بعيد فليعمل الفصح للرب.","9:11":"في الشهر الثاني في اليوم الرابع عشر بين العشاءين يعملونه. على فطير ومرار يأكلونه.","9:12":"لا يبقوا منه إلى الصباح ولا يكسروا عظما منه. حسب كل فرائض الفصح يعملونه.","9:13":"لكن من كان طاهرا وليس في سفر وترك عمل الفصح تقطع تلك النفس من شعبها لأنها لم تقرب قربان الرب في وقته. ذلك الإنسان يحمل خطيته.","9:14":"وإذا نزل عندكم غريب فليعمل فصحا للرب. حسب فريضة الفصح وحكمه كذلك يعمل. فريضة واحدة تكون لكم للغريب ولوطني الأرض».","9:15":"وفي يوم إقامة المسكن غطت السحابة المسكن خيمة الشهادة. وفي المساء كان على المسكن كمنظر نار إلى الصباح.","9:16":"هكذا كان دائما. السحابة تغطيه ومنظر النار ليلا.","9:17":"ومتى ارتفعت السحابة عن الخيمة كان بعد ذلك بنو إسرائيل يرتحلون. وفي المكان حيث حلت السحابة هناك كان بنو إسرائيل ينزلون.","9:18":"حسب قول الرب كان بنو إسرائيل يرتحلون وحسب قول الرب كانوا ينزلون. جميع أيام حلول السحابة على المسكن كانوا ينزلون.","9:19":"وإذا تمادت السحابة على المسكن أياما كثيرة كان بنو إسرائيل يحرسون حراسة الرب ولا يرتحلون.","9:20":"وإذا كانت السحابة أياما قليلة على المسكن فحسب قول الرب كانوا ينزلون وحسب قول الرب كانوا يرتحلون.","9:21":"وإذا كانت السحابة من المساء إلى الصباح ثم ارتفعت السحابة في الصباح كانوا يرتحلون. أو يوما وليلة ثم ارتفعت السحابة كانوا يرتحلون.","9:22":"أو يومين أو شهرا أو سنة متى تمادت السحابة على المسكن حالة عليه كان بنو إسرائيل ينزلون ولا يرتحلون. ومتى ارتفعت كانوا يرتحلون.","9:23":"حسب قول الرب كانوا ينزلون وحسب قول الرب كانوا يرتحلون. وكانوا يحرسون حراسة الرب حسب قول الرب بيد موسى.","10:1":"وأمر الرب موسى:","10:2":"«اصنع لك بوقين من فضة. مسحولين تعملهما فيكونان لك لمناداة الجماعة ولارتحال المحلات.","10:3":"فإذا ضربوا بهما يجتمع إليك كل الجماعة إلى باب خيمة الاجتماع.","10:4":"وإذا ضربوا بواحد يجتمع إليك الرؤساء رؤوس ألوف إسرائيل.","10:5":"وإذا ضربتم هتافا ترتحل المحلات النازلة إلى الشرق.","10:6":"وإذا ضربتم هتافا ثانية ترتحل المحلات النازلة إلى الجنوب. هتافا يضربون لرحلاتهم.","10:7":"وأما عندما تجمعون الجماعة فتضربون ولا تهتفون.","10:8":"وبنو هارون الكهنة يضربون بالأبواق. فتكون لكم فريضة أبدية في أجيالكم.","10:9":"وإذا ذهبتم إلى حرب في أرضكم على عدو يضر بكم تهتفون بالأبواق فتذكرون أمام الرب إلهكم وتخلصون من أعدائكم.","10:10":"وفي يوم فرحكم وفي أعيادكم ورؤوس شهوركم تضربون بالأبواق على محرقاتكم وذبائح سلامتكم فتكون لكم تذكارا أمام إلهكم. أنا الرب إلهكم».","10:11":"وفي السنة الثانية في الشهر الثاني في العشرين من الشهر ارتفعت السحابة عن مسكن الشهادة.","10:12":"فارتحل بنو إسرائيل في رحلاتهم من برية سيناء فحلت السحابة في برية فاران.","10:13":"ارتحلوا أولا حسب قول الرب عن يد موسى.","10:14":"فارتحلت راية محلة بني يهوذا أولا حسب أجنادهم وعلى جنده نحشون بن عميناداب.","10:15":"وعلى جند سبط بني يساكر نثنائيل بن صوغر.","10:16":"وعلى جند سبط بني زبولون أليآب بن حيلون.","10:17":"ثم أنزل المسكن فارتحل بنو جرشون وبنو مراري حاملين المسكن.","10:18":"ثم ارتحلت راية محلة رأوبين حسب أجنادهم وعلى جنده أليصور بن شديئور.","10:19":"وعلى جند سبط بني شمعون شلوميئيل بن صوريشداي.","10:20":"وعلى جند سبط بني جاد ألياساف بن دعوئيل.","10:21":"ثم ارتحل القهاتيون حاملين المقدس. (وأقيم المسكن إلى أن جاءوا)","10:22":"ثم ارتحلت راية محلة بني أفرايم حسب أجنادهم وعلى جنده أليشمع بن عميهود.","10:23":"وعلى جند سبط بني منسى جمليئيل بن فدهصور.","10:24":"وعلى جند سبط بني بنيامين أبيدن بن جدعوني.","10:25":"ثم ارتحلت راية محلة بني دان ساقة جميع المحلات حسب أجنادهم وعلى جنده أخيعزر بن عميشداي.","10:26":"وعلى جند سبط بني أشير فجعيئيل بن عكرن.","10:27":"وعلى جند سبط بني نفتالي أخيرع بن عينن.","10:28":"هذه رحلات بني إسرائيل بأجنادهم حين ارتحلوا.","10:29":"وقال موسى لحوباب بن رعوئيل المدياني حمي موسى: «إننا راحلون إلى المكان الذي قال الرب أعطيكم إياه. اذهب معنا فنحسن إليك لأن الرب قد تكلم عن إسرائيل بالإحسان».","10:30":"فقال له: «لا أذهب بل إلى أرضي وإلى عشيرتي أمضي».","10:31":"فقال: «لا تتركنا لأنه بما أنك تعرف منازلنا في البرية تكون لنا كعيون.","10:32":"وإن ذهبت معنا فبنفس الإحسان الذي يحسن الرب إلينا نحسن نحن إليك».","10:33":"فارتحلوا من جبل الرب مسيرة ثلاثة أيام وتابوت عهد الرب راحل أمامهم مسيرة ثلاثة أيام ليلتمس لهم منزلا.","10:34":"وكانت سحابة الرب عليهم نهارا في ارتحالهم من المحلة.","10:35":"وعند ارتحال التابوت كان موسى يقول: «قم يا رب فلتتبدد أعداؤك ويهرب مبغضوك من أمامك».","10:36":"وعند حلوله كان يقول: «ارجع يا رب إلى ربوات ألوف إسرائيل».","11:1":"وكان الشعب كأنهم يشتكون شرا في أذني الرب. وسمع الرب فحمي غضبه فاشتعلت فيهم نار الرب وأحرقت في طرف المحلة.","11:2":"فصرخ الشعب إلى موسى فصلى موسى إلى الرب فخمدت النار.","11:3":"فدعي اسم ذلك الموضع «تبعيرة» لأن نار الرب اشتعلت فيهم.","11:4":"واللفيف الذي في وسطهم اشتهى شهوة. فعاد بنو إسرائيل أيضا وبكوا وقالوا: «من يطعمنا لحما؟","11:5":"قد تذكرنا السمك الذي كنا نأكله في مصر مجانا والقثاء والبطيخ والكراث والبصل والثوم.","11:6":"والآن قد يبست أنفسنا. ليس شيء غير أن أعيننا إلى هذا المن!»","11:7":"وأما المن فكان كبزر الكزبرة ومنظره كمنظر المقل.","11:8":"كان الشعب يطوفون ليلتقطوه ثم يطحنونه بالرحى أو يدقونه في الهاون ويطبخونه في القدور ويعملونه ملات. وكان طعمه كطعم قطائف بزيت.","11:9":"ومتى نزل الندى على المحلة ليلا كان ينزل المن معه.","11:10":"فلما سمع موسى الشعب يبكون بعشائرهم كل واحد في باب خيمته وحمي غضب الرب جدا ساء ذلك في عيني موسى.","11:11":"فقال موسى للرب: «لماذا أسأت إلى عبدك ولماذا لم أجد نعمة في عينيك حتى أنك وضعت ثقل جميع هذا الشعب علي؟","11:12":"ألعلي حبلت بجميع هذا الشعب أو لعلي ولدته حتى تقول لي احمله في حضنك كما يحمل المربي الرضيع إلى الأرض التي حلفت لآبائه؟","11:13":"من أين لي لحم حتى أعطي جميع هذا الشعب. لأنهم يبكون علي قائلين: أعطنا لحما لنأكل.","11:14":"لا أقدر أنا وحدي أن أحمل جميع هذا الشعب لأنه ثقيل علي.","11:15":"فإن كنت تفعل بي هكذا فاقتلني قتلا إن وجدت نعمة في عينيك فلا أرى بليتي».","11:16":"فقال الرب لموسى: «اجمع إلي سبعين رجلا من شيوخ إسرائيل الذين تعلم أنهم شيوخ الشعب وعرفاؤه وأقبل بهم إلى خيمة الاجتماع فيقفوا هناك معك.","11:17":"فأنزل أنا وأتكلم معك هناك وآخذ من الروح الذي عليك وأضع عليهم فيحملون معك ثقل الشعب فلا تحمل أنت وحدك.","11:18":"وللشعب تقول: تقدسوا للغد فتأكلوا لحما. لأنكم قد بكيتم في أذني الرب قائلين: من يطعمنا لحما؟ إنه كان لنا خير في مصر! فيعطيكم الرب لحما فتأكلون.","11:19":"تأكلون لا يوما واحدا ولا يومين ولا خمسة أيام ولا عشرة أيام ولا عشرين يوما","11:20":"بل شهرا من الزمان حتى يخرج من مناخركم ويصير لكم كراهة لأنكم رفضتم الرب الذي في وسطكم وبكيتم أمامه قائلين: لماذا خرجنا من مصر؟»","11:21":"فقال موسى: «ست مئة ألف ماش هو الشعب الذي أنا في وسطه وأنت قد قلت: أعطيهم لحما ليأكلوا شهرا من الزمان.","11:22":"أيذبح لهم غنم وبقر ليكفيهم أم يجمع لهم كل سمك البحر ليكفيهم؟»","11:23":"فقال الرب لموسى: «هل تقصر يد الرب؟ الآن ترى أيوافيك كلامي أم لا».","11:24":"فخرج موسى وكلم الشعب بكلام الرب وجمع سبعين رجلا من شيوخ الشعب وأوقفهم حوالي الخيمة.","11:25":"فنزل الرب في سحابة وتكلم معه وأخذ من الروح الذي عليه وجعل على السبعين رجلا الشيوخ. فلما حلت عليهم الروح تنبأوا ولكنهم لم يزيدوا.","11:26":"وبقي رجلان في المحلة اسم الواحد ألداد واسم الآخر ميداد فحل عليهما الروح. وكانا من المكتوبين لكنهما لم يخرجا إلى الخيمة. فتنبئا في المحلة.","11:27":"فركض غلام وأخبر موسى وقال: «ألداد وميداد يتنبئان في المحلة».","11:28":"فقال يشوع بن نون خادم موسى (من حداثته): «يا سيدي موسى اردعهما!»","11:29":"فقال له موسى: «هل تغار أنت لي؟ يا ليت كل شعب الرب كانوا أنبياء إذا جعل الرب روحه عليهم!».","11:30":"ثم انحاز موسى إلى المحلة هو وشيوخ إسرائيل.","11:31":"فخرجت ريح من قبل الرب وساقت سلوى من البحر وألقتها على المحلة نحو مسيرة يوم من هنا ومسيرة يوم من هناك حوالي المحلة ونحو ذراعين فوق وجه الأرض.","11:32":"فقام الشعب كل ذلك النهار وكل الليل وكل يوم الغد وجمعوا السلوى. (الذي قلل جمع عشرة حوامر). وسطحوها لهم مساطح حوالي المحلة.","11:33":"وإذ كان اللحم بعد بين أسنانهم قبل أن ينقطع حمي غضب الرب على الشعب وضرب الرب الشعب ضربة عظيمة جدا.","11:34":"فدعي اسم ذلك الموضع «قبروت هتأوة» لأنهم هناك دفنوا القوم الذين اشتهوا.","11:35":"ومن قبروت هتأوة ارتحل الشعب إلى حضيروت فكانوا في حضيروت.","12:1":"وتكلمت مريم وهارون على موسى بسبب المرأة الكوشية التي اتخذها (لأنه كان قد اتخذ امرأة كوشية)","12:2":"فقالا: «هل كلم الرب موسى وحده؟ ألم يكلمنا نحن أيضا؟» فسمع الرب.","12:3":"وأما الرجل موسى فكان حليما جدا أكثر من جميع الناس الذين على وجه الأرض.","12:4":"فقال الرب حالا لموسى وهارون ومريم: «اخرجوا أنتم الثلاثة إلى خيمة الاجتماع». فخرجوا هم الثلاثة.","12:5":"فنزل الرب في عمود سحاب ووقف في باب الخيمة ودعا هارون ومريم فخرجا كلاهما.","12:6":"فقال: «اسمعا كلامي. إن كان منكم نبي للرب فبالرؤيا أستعلن له. في الحلم أكلمه.","12:7":"وأما عبدي موسى فليس هكذا بل هو أمين في كل بيتي.","12:8":"فما إلى فم وعيانا أتكلم معه لا بالألغاز. وشبه الرب يعاين. فلماذا لا تخشيان أن تتكلما على عبدي موسى؟».","12:9":"فحمي غضب الرب عليهما ومضى.","12:10":"فلما ارتفعت السحابة عن الخيمة إذا مريم برصاء كالثلج. فالتفت هارون إلى مريم وإذا هي برصاء.","12:11":"فقال هارون لموسى: «أسألك يا سيدي لا تجعل علينا الخطية التي حمقنا وأخطأنا بها.","12:12":"فلا تكن كالميت الذي يكون عند خروجه من رحم أمه قد أكل نصف لحمه».","12:13":"فصرخ موسى إلى الرب: «اللهم اشفها».","12:14":"فقال الرب لموسى: «ولو بصق أبوها بصقا في وجهها أما كانت تخجل سبعة أيام؟ تحجز سبعة أيام خارج المحلة وبعد ذلك ترجع».","12:15":"فحجزت مريم خارج المحلة سبعة أيام ولم يرتحل الشعب حتى أرجعت مريم.","12:16":"وبعد ذلك ارتحل الشعب من حضيروت ونزلوا في برية فاران.","13:1":"ثم قال الرب لموسى:","13:2":"«أرسل رجالا ليتجسسوا أرض كنعان التي أنا معطيها لبني إسرائيل. رجلا واحدا لكل سبط من آبائه ترسلون. كل واحد رئيس فيهم».","13:3":"فأرسلهم موسى من برية فاران حسب قول الرب. كلهم رجال هم رؤساء بني إسرائيل","13:4":"وهذه أسماؤهم: من سبط رأوبين شموع بن زكور.","13:5":"من سبط شمعون شافاط ابن حوري.","13:6":"من سبط يهوذا كالب بن يفنة.","13:7":"من سبط يساكر يجآل بن يوسف.","13:8":"من سبط أفرايم هوشع بن نون.","13:9":"من سبط بنيامين فلطي بن رافو.","13:10":"من سبط زبولون جديئيل بن سودي.","13:11":"من سبط يوسف: من سبط منسى جدي بن سوسي.","13:12":"من سبط دان عميئيل بن جملي.","13:13":"من سبط أشير ستور بن ميخائيل.","13:14":"من سبط نفتالي نحبي بن وفسي.","13:15":"من سبط جاد جأوئيل بن ماكي.","13:16":"هذه أسماء الرجال الذين أرسلهم موسى ليتجسسوا الأرض. ودعا موسى هوشع بن نون «يشوع».","13:17":"فأرسلهم موسى ليتجسسوا أرض كنعان وقال لهم: «اصعدوا من هنا إلى الجنوب واطلعوا إلى الجبل","13:18":"وانظروا الأرض ما هي؟ والشعب الساكن فيها أقوي هو أم ضعيف؟ قليل أم كثير؟","13:19":"وكيف هي الأرض التي هو ساكن فيها أجيدة أم رديئة؟ وما هي المدن التي هو ساكن فيها أمخيمات أم حصون؟","13:20":"وكيف هي الأرض أسمينة أم هزيلة؟ أفيها شجر أم لا؟ وتشددوا فخذوا من ثمر الأرض». وأما الأيام فكانت أيام باكورات العنب.","13:21":"فصعدوا وتجسسوا الأرض من برية صين إلى رحوب في مدخل حماة.","13:22":"صعدوا إلى الجنوب وأتوا إلى حبرون. وكان هناك أخيمان وشيشاي وتلماي بنو عناق. (وأما حبرون فبنيت قبل صوعن مصر بسبع سنين).","13:23":"وأتوا إلى وادي أشكول وقطفوا من هناك زرجونة بعنقود واحد من العنب وحملوه بالدقرانة بين اثنين مع شيء من الرمان والتين.","13:24":"فدعي ذلك الموضع «وادي أشكول» بسبب العنقود الذي قطعه بنو إسرائيل من هناك.","13:25":"ثم رجعوا من تجسس الأرض بعد أربعين يوما.","13:26":"فساروا حتى أتوا إلى موسى وهارون وكل جماعة بني إسرائيل إلى برية فاران إلى قادش وردوا إليهما خبرا وإلى كل الجماعة وأروهم ثمر الأرض","13:27":"وقالوا: «قد ذهبنا إلى الأرض التي أرسلتنا إليها وحقا إنها تفيض لبنا وعسلا وهذا ثمرها.","13:28":"غير أن الشعب الساكن في الأرض معتز والمدن حصينة عظيمة جدا. وأيضا قد رأينا بني عناق هناك.","13:29":"العمالقة ساكنون في أرض الجنوب والحثيون واليبوسيون والأموريون ساكنون في الجبل والكنعانيون ساكنون عند البحر وعلى جانب الأردن.","13:30":"لكن كالب أنصت الشعب إلى موسى وقال: «إننا نصعد ونمتلكها لأننا قادرون عليها».","13:31":"وأما الرجال الذين صعدوا معه فقالوا: «لا نقدر أن نصعد إلى الشعب لأنهم أشد منا».","13:32":"فأشاعوا مذمة الأرض التي تجسسوها في بني إسرائيل قائلين: «الأرض التي مررنا فيها لنتجسسها هي أرض تأكل سكانها. وجميع الشعب الذي رأينا فيها أناس طوال القامة.","13:33":"وقد رأينا هناك الجبابرة (بني عناق من الجبابرة). فكنا في أعيننا كالجراد وهكذا كنا في أعينهم».","14:1":"فرفعت كل الجماعة صوتها وصرخت. وبكى الشعب تلك الليلة.","14:2":"وتذمر على موسى وعلى هارون جميع بني إسرائيل وقال لهما كل الجماعة: «ليتنا متنا في أرض مصر أو ليتنا متنا في هذا القفر!","14:3":"ولماذا أتى بنا الرب إلى هذه الأرض لنسقط بالسيف؟ تصير نساؤنا وأطفالنا غنيمة. أليس خيرا لنا أن نرجع إلى مصر؟»","14:4":"فقال بعضهم لبعض: «نقيم رئيسا ونرجع إلى مصر».","14:5":"فسقط موسى وهارون على وجهيهما أمام كل معشر جماعة بني إسرائيل.","14:6":"ويشوع بن نون وكالب بن يفنة من الذين تجسسوا الأرض مزقا ثيابهما","14:7":"وقالا لكل جماعة بني إسرائيل: «الأرض التي مررنا فيها لنتجسسها جيدة جدا جدا.","14:8":"إن سر بنا الرب يدخلنا إلى هذه الأرض ويعطينا إياها أرضا تفيض لبنا وعسلا.","14:9":"إنما لا تتمردوا على الرب ولا تخافوا من شعب الأرض لأنهم خبزنا. قد زال عنهم ظلهم والرب معنا. لا تخافوهم».","14:10":"ولكن قال كل الجماعة أن يرجما بالحجارة. ثم ظهر مجد الرب في خيمة الاجتماع لكل بني إسرائيل.","14:11":"وقال الرب لموسى: «حتى متى يهينني هذا الشعب وحتى متى لا يصدقونني بجميع الآيات التي عملت في وسطهم؟","14:12":"إني أضربهم بالوبإ وأبيدهم وأصيرك شعبا أكبر وأعظم منهم».","14:13":"فقال موسى للرب: «فيسمع المصريون الذين أصعدت بقوتك هذا الشعب من وسطهم","14:14":"ويقولون لسكان هذه الأرض الذين قد سمعوا أنك يا رب في وسط هذا الشعب الذين أنت يا رب قد ظهرت لهم عينا لعين وسحابتك واقفة عليهم وأنت سائر أمامهم بعمود سحاب نهارا وبعمود نار ليلا.","14:15":"فإن قتلت هذا الشعب كرجل واحد يقول الشعوب الذين سمعوا بخبرك:","14:16":"لأن الرب لم يقدر أن يدخل هذا الشعب إلى الأرض التي حلف لهم قتلهم في القفر.","14:17":"فالآن لتعظم قدرة سيدي كما قلت:","14:18":"الرب طويل الروح كثير الإحسان يغفر الذنب والسيئة لكنه لا يبرئ. بل يجعل ذنب الآباء على الأبناء إلى الجيل الثالث والرابع.","14:19":"اصفح عن ذنب هذا الشعب كعظمة نعمتك وكما غفرت لهذا الشعب من مصر إلى ههنا».","14:20":"فقال الرب: «قد صفحت حسب قولك.","14:21":"ولكن حي أنا فتملأ كل الأرض من مجد الرب","14:22":"إن جميع الرجال الذين رأوا مجدي وآياتي التي عملتها في مصر وفي البرية وجربوني الآن عشر مرات ولم يسمعوا لقولي","14:23":"لن يروا الأرض التي حلفت لآبائهم. وجميع الذين أهانوني لا يرونها.","14:24":"وأما عبدي كالب فمن أجل أنه كانت معه روح أخرى وقد اتبعني تماما أدخله إلى الأرض التي ذهب إليها وزرعه يرثها.","14:25":"وإذ العمالقة والكنعانيون ساكنون في الوادي فانصرفوا غدا وارتحلوا إلى القفر في طريق بحر سوف».","14:26":"وقال الرب لموسى وهارون:","14:27":"«حتى متى أغفر لهذه الجماعة الشريرة المتذمرة علي؟ قد سمعت تذمر بني إسرائيل الذي يتذمرونه علي.","14:28":"قل لهم: حي أنا يقول الرب لأفعلن بكم كما تكلمتم في أذني.","14:29":"في هذا القفر تسقط جثثكم جميع المعدودين منكم حسب عددكم من ابن عشرين سنة فصاعدا الذين تذمروا علي.","14:30":"لن تدخلوا الأرض التي رفعت يدي لأسكننكم فيها ما عدا كالب بن يفنة ويشوع بن نون.","14:31":"وأما أطفالكم الذين قلتم يكونون غنيمة فإني سأدخلهم فيعرفون الأرض التي احتقرتموها.","14:32":"فجثثكم أنتم تسقط في هذا القفر","14:33":"وبنوكم يكونون رعاة في القفر أربعين سنة ويحملون فجوركم حتى تفنى جثثكم في القفر.","14:34":"كعدد الأيام التي تجسستم فيها الأرض أربعين يوما للسنة يوم. تحملون ذنوبكم أربعين سنة فتعرفون ابتعادي.","14:35":"أنا الرب قد تكلمت. لأفعلن هذا بكل هذه الجماعة الشريرة المتفقة علي. في هذا القفر يفنون وفيه يموتون».","14:36":"أما الرجال الذين أرسلهم موسى ليتجسسوا الأرض ورجعوا وسجسوا عليه كل الجماعة لإشاعة المذمة على الأرض","14:37":"فمات الرجال الذين أشاعوا المذمة الرديئة على الأرض بالوبإ أمام الرب.","14:38":"وأما يشوع بن نون وكالب بن يفنة من أولئك الرجال الذين ذهبوا ليتجسسوا الأرض فعاشا.","14:39":"ولما تكلم موسى بهذا الكلام إلى جميع بني إسرائيل بكى الشعب جدا.","14:40":"ثم بكروا صباحا وصعدوا إلى رأس الجبل قائلين: «هوذا نحن! نصعد إلى الموضع الذي قال الرب عنه فإننا قد أخطأنا».","14:41":"فقال موسى: «لماذا تتجاوزون قول الرب؟ فهذا لا ينجح.","14:42":"لا تصعدوا لأن الرب ليس في وسطكم لئلا تنهزموا أمام أعدائكم.","14:43":"لأن العمالقة والكنعانيين هناك قدامكم تسقطون بالسيف. إنكم قد ارتددتم عن الرب فالرب لا يكون معكم».","14:44":"لكنهم تجبروا وصعدوا إلى رأس الجبل. وأما تابوت عهد الرب وموسى فلم يبرحا من وسط المحلة.","14:45":"فنزل العمالقة والكنعانيون الساكنون في ذلك الجبل وضربوهم وكسروهم إلى حرمة.","15:1":"وقال الرب لموسى:","15:2":"«قل لبني إسرائيل: متى جئتم إلى أرض مسكنكم التي أنا أعطيكم","15:3":"وعملتم وقودا للرب محرقة أو ذبيحة وفاء لنذر أو نافلة أو في أعيادكم لعمل رائحة سرور للرب من البقر أو من الغنم","15:4":"يقرب الذي قرب قربانه للرب تقدمة من دقيق عشرا ملتوتا بربع الهين من الزيت","15:5":"وخمرا للسكيب ربع الهين. تعمل على المحرقة أو الذبيحة للخروف الواحد.","15:6":"لكن للكبش تعمل تقدمة من دقيق عشرين ملتوتين بثلث الهين من الزيت","15:7":"وخمرا للسكيب ثلث الهين تقرب لرائحة سرور للرب.","15:8":"وإذا عملت ابن بقر محرقة أو ذبيحة وفاء لنذر أو ذبيحة سلامة للرب","15:9":"تقرب على ابن البقر تقدمة من دقيق ثلاثة أعشار ملتوتة بنصف الهين من الزيت","15:10":"وخمرا تقرب للسكيب نصف الهين وقود رائحة سرور للرب.","15:11":"هكذا يعمل للثور الواحد أو للكبش الواحد أو للشاة من الضأن أو من المعز.","15:12":"كالعدد الذي تعملون هكذا تعملون لكل واحد حسب عددهن.","15:13":"كل وطني يعمل هذه هكذا لتقريب وقود رائحة سرور للرب.","15:14":"وإذا نزل عندكم غريب أو كان أحد في وسطكم في أجيالكم وعمل وقود رائحة سرور للرب فكما تفعلون كذلك يفعل.","15:15":"أيتها الجماعة لكم وللغريب النازل عندكم فريضة واحدة دهرية في أجيالكم. مثلكم يكون مثل الغريب أمام الرب.","15:16":"شريعة واحدة وحكم واحد يكون لكم وللغريب النازل عندكم.","15:17":"وقال الرب لموسى:","15:18":"«قل لبني إسرائيل: متى دخلتم الأرض التي أنا آت بكم إليها","15:19":"فعندما تأكلون من خبز الأرض ترفعون رفيعة للرب.","15:20":"أول عجينكم ترفعون قرصا رفيعة. كرفيعة البيدر هكذا ترفعونه.","15:21":"من أول عجينكم تعطون للرب رفيعة في أجيالكم.","15:22":"«وإذا سهوتم ولم تعملوا جميع هذه الوصايا التي كلم بها الرب موسى","15:23":"جميع ما أمركم به الرب عن يد موسى من اليوم الذي أمر فيه الرب فصاعدا في أجيالكم","15:24":"فإن عمل خفية عن أعين الجماعة سهوا يعمل كل الجماعة ثورا واحدا ابن بقر محرقة لرائحة سرور للرب مع تقدمته وسكيبه كالعادة وتيسا واحدا من المعز ذبيحة خطية.","15:25":"فيكفر الكاهن عن كل جماعة بني إسرائيل فيصفح عنهم لأنه كان سهوا. فإذا أتوا بقربانهم وقودا للرب وبذبيحة خطيتهم أمام الرب لأجل سهوهم","15:26":"يصفح عن كل جماعة بني إسرائيل والغريب النازل بينهم لأنه حدث لجميع الشعب بسهو.","15:27":"«وإن أخطأت نفس واحدة سهوا تقرب عنزا حولية ذبيحة خطية","15:28":"فيكفر الكاهن عن النفس التي سهت عندما أخطأت بسهو أمام الرب للتكفير عنها فيصفح عنها.","15:29":"للوطني في بني إسرائيل وللغريب النازل بينهم تكون شريعة واحدة للعامل بسهو.","15:30":"وأما النفس التي تعمل بيد رفيعة من الوطنيين أو من الغرباء فهي تزدري بالرب. فتقطع تلك النفس من بين شعبها","15:31":"لأنها احتقرت كلام الرب ونقضت وصيته. قطعا تقطع تلك النفس. ذنبها عليها».","15:32":"ولما كان بنو إسرائيل في البرية وجدوا رجلا يحتطب حطبا في يوم السبت.","15:33":"فقدمه الذين وجدوه يحتطب حطبا إلى موسى وهارون وكل الجماعة.","15:34":"فوضعوه في المحرس لأنه لم يعلن ماذا يفعل به.","15:35":"فقال الرب لموسى: «قتلا يقتل الرجل. يرجمه بحجارة كل الجماعة خارج المحلة».","15:36":"فأخرجه كل الجماعة إلى خارج المحلة ورجموه بحجارة فمات كما أمر الرب موسى.","15:37":"وقال الرب لموسى:","15:38":"«قل لبني إسرائيل أن يصنعوا لهم أهدابا في أذيال ثيابهم في أجيالهم ويجعلوا على هدب الذيل عصابة من أسمانجوني.","15:39":"فتكون لكم هدبا فترونها وتذكرون كل وصايا الرب وتعملونها ولا تطوفون وراء قلوبكم وأعينكم التي أنتم فاسقون وراءها","15:40":"لكي تذكروا وتعملوا كل وصاياي وتكونوا مقدسين لإلهكم.","15:41":"أنا الرب إلهكم الذي أخرجكم من أرض مصر ليكون لكم إلها. أنا الرب إلهكم».","16:1":"وأخذ قورح بن يصهار بن قهات بن لاوي وداثان وأبيرام ابنا أليآب وأون بن فالت بنو رأوبين","16:2":"يقاومون موسى مع أناس من بني إسرائيل مئتين وخمسين رؤساء الجماعة مدعوين للاجتماع ذوي اسم.","16:3":"فاجتمعوا على موسى وهارون وقالوا لهما: «كفاكما! إن كل الجماعة بأسرها مقدسة وفي وسطها الرب. فما بالكما ترتفعان على جماعة الرب؟».","16:4":"فلما سمع موسى سقط على وجهه.","16:5":"ثم قال لقورح وجميع قومه: «غدا يعلن الرب من هو له ومن المقدس حتى يقربه إليه. فالذي يختاره يقربه إليه.","16:6":"افعلوا هذا: خذوا لكم مجامر. قورح وكل جماعته.","16:7":"واجعلوا فيها نارا وضعوا عليها بخورا أمام الرب غدا. فالرجل الذي يختاره الرب هو المقدس. كفاكم يا بني لاوي!»","16:8":"وقال موسى لقورح: «اسمعوا يا بني لاوي.","16:9":"أقليل عليكم أن إله إسرائيل أفرزكم من جماعة إسرائيل ليقربكم إليه لكي تعملوا خدمة مسكن الرب وتقفوا قدام الجماعة لخدمتها؟","16:10":"فقربك وجميع إخوتك بني لاوي معك وتطلبون أيضا كهنوتا!","16:11":"إذن أنت وكل جماعتك متفقون على الرب. وأما هارون فما هو حتى تتذمروا عليه؟»","16:12":"فأرسل موسى ليدعو داثان وأبيرام ابني أليآب. فقالا: «لا نصعد!","16:13":"أقليل أنك أصعدتنا من أرض تفيض لبنا وعسلا لتميتنا في البرية حتى تترأس علينا ترؤسا؟","16:14":"كذلك لم تأت بنا إلى أرض تفيض لبنا وعسلا ولا أعطيتنا نصيب حقول وكروم. هل تقلع أعين هؤلاء القوم؟ لا نصعد!».","16:15":"فاغتاظ موسى جدا وقال للرب: «لا تلتفت إلى تقدمتهما. حمارا واحدا لم آخذ منهم ولا أسأت إلى أحد منهم».","16:16":"وقال موسى لقورح: «كن أنت وكل جماعتك أمام الرب أنت وهم وهارون غدا","16:17":"وخذوا كل واحد مجمرته واجعلوا فيها بخورا وقدموا أمام الرب كل واحد مجمرته.مئتين وخمسين مجمرة. وأنت وهارون كل واحد مجمرته».","16:18":"فأخذوا كل واحد مجمرته وجعلوا فيها نارا ووضعوا عليها بخورا ووقفوا لدى باب خيمة الاجتماع مع موسى وهارون.","16:19":"وجمع عليهما قورح كل الجماعة إلى باب خيمة الاجتماع فتراءى مجد الرب لكل الجماعة.","16:20":"وقال الرب لموسى وهارون:","16:21":"«افترزا من بين هذه الجماعة فإني أفنيهم في لحظة!»","16:22":"فخرا على وجهيهما وقالا: «اللهم إله أرواح جميع البشر هل يخطئ رجل واحد فتسخط على كل الجماعة؟»","16:23":"فقال الرب لموسى:","16:24":"«كلم الجماعة قائلا اطلعوا من حوالي مسكن قورح وداثان وأبيرام».","16:25":"فقام موسى وذهب إلى داثان وأبيرام وذهب وراءه شيوخ إسرائيل.","16:26":"فقال للجماعة: «اعتزلوا عن خيام هؤلاء القوم البغاة ولا تمسوا شيئا مما لهم لئلا تهلكوا بجميع خطاياهم».","16:27":"فطلعوا من حوالي مسكن قورح وداثان وأبيرام وخرج داثان وأبيرام ووقفا في باب خيمتيهما مع نسائهما وبنيهما وأطفالهما.","16:28":"فقال موسى: «بهذا تعلمون أن الرب قد أرسلني لأعمل كل هذه الأعمال وأنها ليست من نفسي.","16:29":"إن مات هؤلاء كموت كل إنسان وأصابتهم مصيبة كل إنسان فليس الرب قد أرسلني.","16:30":"ولكن إن ابتدع الرب بدعة وفتحت الأرض فاها وابتلعتهم وكل ما لهم فهبطوا أحياء إلى الهاوية تعلمون أن هؤلاء القوم قد ازدروا بالرب».","16:31":"فلما فرغ من التكلم بكل هذا الكلام انشقت الأرض التي تحتهم","16:32":"وفتحت الأرض فاها وابتلعتهم وبيوتهم وكل من كان لقورح مع كل الأموال","16:33":"فنزلوا هم وكل ما كان لهم أحياء إلى الهاوية وانطبقت عليهم الأرض فبادوا من بين الجماعة.","16:34":"وكل إسرائيل الذين حولهم هربوا من صوتهم لأنهم قالوا: «لعل الأرض تبتلعنا».","16:35":"وخرجت نار من عند الرب وأكلت المئتين والخمسين رجلا الذين قربوا البخور.","16:36":"ثم قال الرب لموسى:","16:37":"«قل لألعازار بن هارون الكاهن أن يرفع المجامر من الحريق واذر النار هناك فإنهن قد تقدسن.","16:38":"مجامر هؤلاء المخطئين ضد نفوسهم فليعملوها صفائح مطروقة غشاء للمذبح لأنهم قد قدموها أمام الرب فتقدست. فتكون علامة لبني إسرائيل».","16:39":"فأخذ ألعازار الكاهن مجامر النحاس التي قدمها المحترقون وطرقوها غشاء للمذبح","16:40":"تذكارا لبني إسرائيل لكي لا يقترب رجل أجنبي ليس من نسل هارون ليبخر بخورا أمام الرب فيكون مثل قورح وجماعته كما كلمه الرب عن يد موسى.","16:41":"فتذمر كل جماعة بني إسرائيل في الغد على موسى وهارون قائلين: «أنتما قد قتلتما شعب الرب».","16:42":"ولما اجتمعت الجماعة على موسى وهارون انصرفا إلى خيمة الاجتماع وإذا هي قد غطتها السحابة وتراءى مجد الرب.","16:43":"فجاء موسى وهارون إلى قدام خيمة الاجتماع.","16:44":"فقال الرب لموسى:","16:45":"«اطلعا من وسط هذه الجماعة فإني أفنيهم بلحظة». فخرا على وجهيهما.","16:46":"ثم قال موسى لهارون: «خذ المجمرة واجعل فيها نارا من على المذبح وضع بخورا واذهب بها مسرعا إلى الجماعة وكفر عنهم لأن السخط قد خرج من قبل الرب. قد ابتدأ الوبأ».","16:47":"فأخذ هارون كما قال موسى وركض إلى وسط الجماعة وإذا الوبأ قد ابتدأ في الشعب. فوضع البخور وكفر عن الشعب.","16:48":"ووقف بين الموتى والأحياء فامتنع الوبأ.","16:49":"فكان الذين ماتوا بالوبإ أربعة عشر ألفا وسبع مئة عدا الذين ماتوا بسبب قورح.","16:50":"ثم رجع هارون إلى موسى إلى باب خيمة الاجتماع والوبأ قد امتنع.","17:1":"وقال الرب لموسى:","17:2":"«كلم بني إسرائيل وخذ منهم عصا عصا لكل بيت أب من جميع رؤسائهم حسب بيوت آبائهم. اثنتي عشرة عصا. واسم كل واحد تكتبه على عصاه.","17:3":"واسم هارون تكتبه على عصا لاوي لأن لرأس بيت آبائهم عصا واحدة.","17:4":"وضعها في خيمة الاجتماع أمام الشهادة حيث أجتمع بكم.","17:5":"فالرجل الذي أختاره تفرخ عصاه فأسكن عني تذمرات بني إسرائيل التي يتذمرونها عليكما».","17:6":"فكلم موسى بني إسرائيل فأعطاه جميع رؤسائهم عصا عصا لكل رئيس حسب بيوت آبائهم. اثنتي عشرة عصا. وعصا هارون بين عصيهم.","17:7":"فوضع موسى العصي أمام الرب في خيمة الشهادة.","17:8":"وفي الغد دخل موسى إلى خيمة الشهادة وإذا عصا هارون لبيت لاوي قد أفرخت. أخرجت فروخا وأزهرت زهرا وأنضجت لوزا.","17:9":"فأخرج موسى جميع العصي من أمام الرب إلى جميع بني إسرائيل فنظروا وأخذ كل واحد عصاه.","17:10":"وقال الرب لموسى: «رد عصا هارون إلى أمام الشهادة لأجل الحفظ علامة لبني التمرد فتكف تذمراتهم عني لكي لا يموتوا».","17:11":"ففعل موسى كما أمره الرب. كذلك فعل.","17:12":"فقال بنو إسرائيل لموسى: «إننا فنينا وهلكنا. قد هلكنا جميعا.","17:13":"كل من اقترب إلى مسكن الرب يموت! أما فنينا تماما؟».","18:1":"وقال الرب لهارون: «أنت وبنوك وبيت أبيك معك تحملون ذنب المقدس. وأنت وبنوك معك تحملون ذنب كهنوتكم.","18:2":"وأيضا إخوتك سبط لاوي سبط أبيك قربهم معك فيقترنوا بك ويوازروك وأنت وبنوك قدام خيمة الشهادة","18:3":"فيحفظون حراستك وحراسة الخيمة كلها. ولكن إلى أمتعة القدس وإلى المذبح لا يقتربون لئلا يموتوا هم وأنتم جميعا.","18:4":"يقترنون بك ويحفظون حراسة خيمة الاجتماع مع كل خدمة الخيمة. والأجنبي لا يقترب إليكم.","18:5":"بل تحفظون أنتم حراسة القدس وحراسة المذبح لكي لا يكون أيضا سخط على بني إسرائيل.","18:6":"هئنذا قد أخذت إخوتكم اللاويين من بين بني إسرائيل عطية لكم معطين للرب ليخدموا خدمة خيمة الاجتماع.","18:7":"وأما أنت وبنوك معك فتحفظون كهنوتكم مع ما للمذبح وما هو داخل الحجاب وتخدمون خدمة. عطية أعطيت كهنوتكم. والأجنبي الذي يقترب يقتل».","18:8":"وقال الرب لهارون: «وهئنذا قد أعطيتك حراسة رفائعي. مع جميع أقداس بني إسرائيل لك أعطيتها حق المسحة ولبنيك فريضة دهرية.","18:9":"هذا يكون لك من قدس الأقداس من النار كل قرابينهم مع كل تقدماتهم وكل ذبائح خطاياهم وكل ذبائح آثامهم التي يردونها لي. قدس أقداس هي لك ولبنيك.","18:10":"في قدس الأقداس تأكلها. كل ذكر يأكلها. قدسا تكون لك.","18:11":"وهذه لك: الرفيعة من عطاياهم مع كل ترديدات بني إسرائيل. لك أعطيتها ولبنيك وبناتك معك فريضة دهرية. كل طاهر في بيتك يأكل منها.","18:12":"كل دسم الزيت وكل دسم المسطار والحنطة أبكارهن التي يعطونها للرب لك أعطيتها.","18:13":"أبكار كل ما في أرضهم التي يقدمونها للرب لك تكون. كل طاهر في بيتك يأكلها.","18:14":"كل محرم في إسرائيل يكون لك.","18:15":"كل فاتح رحم من كل جسد يقدمونه للرب من الناس ومن البهائم يكون لك. غير أنك تقبل فداء بكر الإنسان وبكر البهيمة النجسة تقبل فداءه.","18:16":"وفداؤه من ابن شهر تقبله حسب تقويمك فضة خمسة شواقل على شاقل القدس. هو عشرون جيرة.","18:17":"لكن بكر البقر أو بكر الضأن أو بكر المعز لا تقبل فداءه. إنه قدس. بل ترش دمه على المذبح وتوقد شحمه وقودا رائحة سرور للرب.","18:18":"ولحمه يكون لك كصدر الترديد والساق اليمنى يكون لك.","18:19":"جميع رفائع الأقداس التي يرفعها بنو إسرائيل للرب أعطيتها لك ولبنيك وبناتك معك حقا دهريا. ميثاق ملح دهريا أمام الرب لك ولزرعك معك».","18:20":"وقال الرب لهارون: «لا تنال نصيبا في أرضهم ولا يكون لك قسم في وسطهم. أنا قسمك ونصيبك في وسط بني إسرائيل.","18:21":"«وأما بنو لاوي فإني قد أعطيتهم كل عشر في إسرائيل ميراثا عوض خدمة خيمة الاجتماع التي يخدمونها.","18:22":"فلا يقترب أيضا بنو إسرائيل إلى خيمة الاجتماع ليحملوا خطية للموت","18:23":"بل اللاويون يخدمون خدمة خيمة الاجتماع وهم يحملون ذنبهم فريضة دهرية في أجيالكم. وفي وسط إسرائيل لا ينالون نصيبا.","18:24":"إن عشور بني إسرائيل التي يرفعونها للرب رفيعة قد أعطيتها للاويين نصيبا. لذلك قلت لهم: في وسط بني إسرائيل لا ينالون نصيبا».","18:25":"وقال الرب لموسى:","18:26":"«للاويين تقول: متى أخذتم من بني إسرائيل العشر الذي أعطيتكم إياه من عندهم نصيبا لكم ترفعون منه رفيعة الرب: عشرا من العشر","18:27":"فيحسب لكم. إنه رفيعتكم كالحنطة من البيدر وكالملء من المعصرة.","18:28":"فهكذا ترفعون أنتم أيضا رفيعة الرب من جميع عشوركم التي تأخذون من بني إسرائيل. تعطون منها رفيعة الرب لهارون الكاهن.","18:29":"من جميع عطاياكم ترفعون كل رفيعة الرب من الكل دسمه المقدس منه.","18:30":"وتقول لهم: حين ترفعون دسمه منه يحسب للاويين كمحصول البيدر وكمحصول المعصرة.","18:31":"وتأكلونه في كل مكان أنتم وبيوتكم لأنه أجرة لكم عوض خدمتكم في خيمة الاجتماع.","18:32":"ولا تتحملون بسببه خطية إذا رفعتم دسمه منه. وأما أقداس بني إسرائيل فلا تدنسوها لئلا تموتوا».","19:1":"وقال الرب لموسى وهارون:","19:2":"«هذه فريضة الشريعة التي أمر بها الرب: كلم بني إسرائيل أن يأخذوا إليك بقرة حمراء صحيحة لا عيب فيها ولم يعل عليها نير","19:3":"فتعطونها لألعازار الكاهن فتخرج إلى خارج المحلة وتذبح قدامه.","19:4":"ويأخذ ألعازار الكاهن من دمها بإصبعه وينضح من دمها إلى جهة وجه خيمة الاجتماع سبع مرات.","19:5":"وتحرق البقرة أمام عينيه. يحرق جلدها ولحمها ودمها مع فرثها.","19:6":"ويأخذ الكاهن خشب أرز وزوفا وقرمزا ويطرحهن في وسط حريق البقرة","19:7":"ثم يغسل الكاهن ثيابه ويرحض جسده بماء وبعد ذلك يدخل المحلة. ويكون الكاهن نجسا إلى المساء.","19:8":"والذي أحرقها يغسل ثيابه بماء ويرحض جسده بماء ويكون نجسا إلى المساء.","19:9":"ويجمع رجل طاهر رماد البقرة ويضعه خارج المحلة في مكان طاهر فتكون لجماعة بني إسرائيل في حفظ ماء نجاسة. إنها ذبيحة خطية.","19:10":"والذي جمع رماد البقرة يغسل ثيابه ويكون نجسا إلى المساء. فتكون لبني إسرائيل وللغريب النازل في وسطهم فريضة دهرية.","19:11":"«من مس ميتا ميتة إنسان ما يكون نجسا سبعة أيام.","19:12":"يتطهر به في اليوم الثالث وفي اليوم السابع يكون طاهرا. وإن لم يتطهر في اليوم الثالث ففي اليوم السابع لا يكون طاهرا.","19:13":"كل من مس ميتا ميتة إنسان قد مات ولم يتطهر ينجس مسكن الرب. فتقطع تلك النفس من إسرائيل. لأن ماء النجاسة لم يرش عليها تكون نجسة. نجاستها لم تزل فيها.","19:14":"«هذه هي الشريعة: إذا مات إنسان في خيمة فكل من دخل الخيمة وكل من كان في الخيمة يكون نجسا سبعة أيام.","19:15":"وكل إناء مفتوح ليس عليه سداد بعصابة فإنه نجس.","19:16":"وكل من مس على وجه الصحراء قتيلا بالسيف أو ميتا أو عظم إنسان أو قبرا يكون نجسا سبعة أيام.","19:17":"فيأخذون للنجس من غبار حريق ذبيحة الخطية ويجعل عليه ماء حيا في إناء.","19:18":"ويأخذ رجل طاهر زوفا ويغمسها في الماء وينضحه على الخيمة وعلى جميع الأمتعة وعلى الأنفس الذين كانوا هناك وعلى الذي مس العظم أو القتيل أو الميت أو القبر.","19:19":"ينضح الطاهر على النجس في اليوم الثالث واليوم السابع. ويطهره في اليوم السابع فيغسل ثيابه ويرحض بماء فيكون طاهرا في المساء.","19:20":"وأما الإنسان الذي يتنجس ولا يتطهر فتباد تلك النفس من بين الجماعة لأنه نجس مقدس الرب. ماء النجاسة لم يرش عليه. إنه نجس.","19:21":"فتكون لهم فريضة دهرية. والذي رش ماء النجاسة يغسل ثيابه والذي مس ماء النجاسة يكون نجسا إلى المساء.","19:22":"وكل ما مسه النجس يتنجس والنفس التي تمس تكون نجسة إلى المساء».","20:1":"وأتى بنو إسرائيل الجماعة كلها إلى برية صين في الشهر الأول. وأقام الشعب في قادش. وماتت هناك مريم ودفنت هناك.","20:2":"ولم يكن ماء للجماعة فاجتمعوا على موسى وهارون.","20:3":"وخاصم الشعب موسى وقالوا له: «ليتنا فنينا فناء إخوتنا أمام الرب.","20:4":"لماذا أتيتما بجماعة الرب إلى هذه البرية لكي نموت فيها نحن ومواشينا؟","20:5":"ولماذا أصعدتمانا من مصر لتأتيا بنا إلى هذا المكان الرديء؟ ليس هو مكان زرع وتين وكرم ورمان ولا فيه ماء للشرب».","20:6":"فأتى موسى وهارون من أمام الجماعة إلى باب خيمة الاجتماع وسقطا على وجهيهما. فتراءى لهما مجد الرب.","20:7":"وأمر الرب موسى:","20:8":"«خذ العصا واجمع الجماعة أنت وهارون أخوك وكلما الصخرة أمام أعينهم أن تعطي ماءها فتخرج لهم ماء من الصخرة وتسقي الجماعة ومواشيهم».","20:9":"فأخذ موسى العصا من أمام الرب كما أمره","20:10":"وجمع موسى وهارون الجمهور أمام الصخرة فقال لهم: «اسمعوا أيها المردة! أمن هذه الصخرة نخرج لكم ماء؟»","20:11":"ورفع موسى يده وضرب الصخرة بعصاه مرتين فخرج ماء غزير فشربت الجماعة ومواشيها.","20:12":"فقال الرب لموسى وهارون: «من أجل أنكما لم تؤمنا بي حتى تقدساني أمام أعين بني إسرائيل لذلك لا تدخلان هذه الجماعة إلى الأرض التي أعطيتهم إياها».","20:13":"هذا ماء مريبة حيث خاصم بنو إسرائيل الرب فتقدس فيهم.","20:14":"وأرسل موسى رسلا من قادش إلى ملك أدوم: «هكذا يقول أخوك إسرائيل قد عرفت كل المشقة التي أصابتنا.","20:15":"إن آباءنا انحدروا إلى مصر وأقمنا في مصر أياما كثيرة وأساء المصريون إلينا وإلى آبائنا","20:16":"فصرخنا إلى الرب فسمع صوتنا وأرسل ملاكا وأخرجنا من مصر. وها نحن في قادش مدينة في طرف تخومك.","20:17":"دعنا نمر في أرضك. لا نمر في حقل ولا في كرم ولا نشرب ماء بئر. في طريق الملك نمشي لا نميل يمينا ولا يسارا حتى نتجاوز تخومك».","20:18":"فقال له أدوم: «لا تمر بي لئلا أخرج للقائك بالسيف».","20:19":"فقال له بنو إسرائيل: «في السكة نصعد. وإذا شربنا أنا ومواشي من مائك أدفع ثمنه. لا شيء. أمر برجلي فقط.","20:20":"فقال: «لا تمر». وخرج أدوم للقائه بشعب غفير وبيد شديدة.","20:21":"وأبى أدوم أن يسمح لإسرائيل بالمرور في تخومه فتحول إسرائيل عنه.","20:22":"فارتحل بنو إسرائيل الجماعة كلها من قادش وأتوا إلى جبل هور.","20:23":"وقال الرب لموسى وهارون في جبل هور على تخم أرض أدوم:","20:24":"«يضم هارون إلى قومه لأنه لا يدخل الأرض التي أعطيت لبني إسرائيل لأنكم عصيتم قولي عند ماء مريبة.","20:25":"خذ هارون وألعازار ابنه واصعد بهما إلى جبل هور","20:26":"واخلع عن هارون ثيابه وألبس ألعازار ابنه إياها. فيضم هارون ويموت هناك».","20:27":"ففعل موسى كما أمر الرب وصعدوا إلى جبل هور أمام أعين كل الجماعة.","20:28":"فخلع موسى عن هارون ثيابه وألبس ألعازار ابنه إياها. فمات هارون هناك على رأس الجبل. ثم انحدر موسى وألعازار عن الجبل.","20:29":"فلما رأى كل الجماعة أن هارون قد مات بكى جميع بيت إسرائيل على هارون ثلاثين يوما.","21:1":"ولما سمع الكنعاني ملك عراد الساكن في الجنوب أن إسرائيل جاء في طريق أتاريم حارب إسرائيل وسبى منهم سبيا.","21:2":"فنذر إسرائيل نذرا للرب وقال: «إن دفعت هؤلاء القوم إلى يدي أحرم مدنهم».","21:3":"فسمع الرب لقول إسرائيل ودفع الكنعانيين فحرموهم ومدنهم. فدعي اسم المكان «حرمة».","21:4":"وارتحلوا من جبل هور في طريق بحر سوف ليدوروا بأرض أدوم فضاقت نفس الشعب في الطريق.","21:5":"وتكلم الشعب على الله وعلى موسى قائلين: «لماذا أصعدتمانا من مصر لنموت في البرية! لأنه لا خبز ولا ماء وقد كرهت أنفسنا الطعام السخيف».","21:6":"فأرسل الرب على الشعب الحيات المحرقة فلدغت الشعب فمات قوم كثيرون من إسرائيل.","21:7":"فأتى الشعب إلى موسى وقالوا: «قد أخطأنا إذ تكلمنا على الرب وعليك فصل إلى الرب ليرفع عنا الحيات». فصلى موسى لأجل الشعب.","21:8":"فقال الرب لموسى: «اصنع لك حية محرقة وضعها على راية فكل من لدغ ونظر إليها يحيا».","21:9":"فصنع موسى حية من نحاس ووضعها على الراية فكان متى لدغت حية إنسانا ونظر إلى حية النحاس يحيا.","21:10":"وارتحل بنو إسرائيل ونزلوا في أوبوت.","21:11":"وارتحلوا من أوبوت ونزلوا في عيي عباريم في البرية التي قبالة موآب إلى شروق الشمس.","21:12":"من هناك ارتحلوا ونزلوا في وادي زارد.","21:13":"من هناك ارتحلوا ونزلوا في عبر أرنون الذي في البرية خارجا عن تخم الأموريين. لأن أرنون هو تخم موآب بين موآب والأموريين.","21:14":"لذلك يقال في كتاب «حروب الرب»: «واهب في سوفة وأودية أرنون","21:15":"ومصب الأودية الذي مال إلى مسكن عار واستند إلى تخم موآب».","21:16":"ومن هناك إلى بئر. وهي البئر حيث قال الرب لموسى: «اجمع الشعب فأعطيهم ماء».","21:17":"حينئذ ترنم إسرائيل بهذا النشيد: «اصعدي أيتها البئر! أجيبوا لها.","21:18":"بئر حفرها رؤساء حفرها شرفاء الشعب بصولجان بعصيهم». ومن البرية إلى متانة","21:19":"ومن متانة إلى نحليئيل ومن نحليئيل إلى باموت","21:20":"ومن باموت إلى الجواء التي في صحراء موآب عند رأس الفسجة التي تشرف على وجه البرية.","21:21":"وأرسل إسرائيل رسلا إلى سيحون ملك الأموريين قائلا:","21:22":"«دعني أمر في أرضك. لا نميل إلى حقل ولا إلى كرم ولا نشرب ماء بئر. في طريق الملك نمشي حتى نتجاوز تخومك».","21:23":"فلم يسمح سيحون لإسرائيل بالمرور في تخومه بل جمع سيحون جميع قومه وخرج للقاء إسرائيل إلى البرية فأتى إلى ياهص وحارب إسرائيل.","21:24":"فضربه إسرائيل بحد السيف وملك أرضه من أرنون إلى يبوق إلى بني عمون. لأن تخم بني عمون كان قويا.","21:25":"فأخذ إسرائيل كل هذه المدن وأقام إسرائيل في جميع مدن الأموريين في حشبون وفي كل قراها.","21:26":"لأن حشبون كانت مدينة سيحون ملك الأموريين وكان قد حارب ملك موآب الأول وأخذ كل أرضه من يده حتى أرنون.","21:27":"لذلك يقول أصحاب الأمثال: «ايتوا إلى حشبون فتبنى وتصلح مدينة سيحون.","21:28":"لأن نارا خرجت من حشبون. لهيبا من قرية سيحون. أكلت عار موآب. أهل مرتفعات أرنون.","21:29":"ويل لك يا موآب. هلكت يا أمة كموش. قد صير بنيه هاربين وبناته في السبي لملك الأموريين سيحون.","21:30":"لكن قد رميناهم. هلكت حشبون إلى ديبون. وأخربنا إلى نوفح التي إلى ميدبا».","21:31":"فأقام إسرائيل في أرض الأموريين.","21:32":"وأرسل موسى ليتجسس يعزير فأخذوا قراها وطردوا الأموريين الذين هناك.","21:33":"ثم تحولوا وصعدوا في طريق باشان. فخرج عوج ملك باشان للقائهم هو وجميع قومه إلى الحرب في إذرعي.","21:34":"فقال الرب لموسى: «لا تخف منه لأني قد دفعته إلى يدك مع جميع قومه وأرضه فتفعل به كما فعلت بسيحون ملك الأموريين الساكن في حشبون».","21:35":"فضربوه وبنيه وجميع قومه حتى لم يبق له شارد وملكوا أرضه.","22:1":"وارتحل بنو إسرائيل ونزلوا في عربات موآب من عبر أردن أريحا.","22:2":"ولما رأى بالاق بن صفور جميع ما فعل إسرائيل بالأموريين","22:3":"فزع موآب من الشعب جدا لأنه كثير وضجر موآب من قبل بني إسرائيل.","22:4":"فقال موآب لشيوخ مديان: «الآن يلحس الجمهور كل ما حولنا كما يلحس الثور خضرة الحقل». وكان بالاق بن صفور ملكا لموآب في ذلك الزمان.","22:5":"فأرسل رسلا إلى بلعام بن بعور إلى فتور التي على النهر في أرض بني شعبه ليدعوه قائلا: «هوذا شعب قد خرج من مصر. هوذا قد غشى وجه الأرض وهو مقيم مقابلي.","22:6":"فالآن تعال والعن لي هذا الشعب لأنه أعظم مني. لعله يمكننا أن نكسره فأطرده من الأرض. لأني عرفت أن الذي تباركه مبارك والذي تلعنه ملعون».","22:7":"فانطلق شيوخ موآب وشيوخ مديان وحلوان العرافة في أيديهم وأتوا إلى بلعام وكلموه بكلام بالاق.","22:8":"فقال لهم: «بيتوا هنا الليلة فأرد عليكم جوابا كما يكلمني الرب». فمكث رؤساء موآب عند بلعام.","22:9":"فأتى الله إلى بلعام وقال: «من هم هؤلاء الرجال الذين عندك؟»","22:10":"فقال بلعام لله: «بالاق بن صفور ملك موآب قد أرسل إلي يقول:","22:11":"هوذا الشعب الخارج من مصر قد غشى وجه الأرض. تعال الآن العن لي إياه لعلي أقدر أن أحاربه وأطرده».","22:12":"فقال الله لبلعام: «لا تذهب معهم ولا تلعن الشعب لأنه مبارك».","22:13":"فقام بلعام صباحا وقال لرؤساء بالاق: «انطلقوا إلى أرضكم لأن الرب أبى أن يسمح لي بالذهاب معكم».","22:14":"فقام رؤساء موآب وأتوا إلى بالاق وقالوا: «أبى بلعام أن يأتي معنا».","22:15":"فعاد بالاق وأرسل أيضا رؤساء أكثر وأعظم من أولئك.","22:16":"فأتوا إلى بلعام وقالوا له: «هكذا قال بالاق بن صفور: لا تمتنع من الإتيان إلي","22:17":"لأني أكرمك إكراما عظيما وكل ما تقول لي أفعله. فتعال الآن العن لي هذا الشعب».","22:18":"فأجاب بلعام عبيد بالاق: «ولو أعطاني بالاق ملء بيته فضة وذهبا لا أقدر أن أتجاوز قول الرب إلهي لأعمل صغيرا أو كبيرا.","22:19":"فالآن امكثوا هنا أنتم أيضا هذه الليلة لأعلم ماذا يعود الرب يكلمني به».","22:20":"فأتى الله إلى بلعام ليلا وقال له: «إن أتى الرجال ليدعوك فقم اذهب معهم. إنما تعمل الأمر الذي أكلمك به فقط».","22:21":"فقام بلعام صباحا وشد على أتانه وانطلق مع رؤساء موآب.","22:22":"فحمي غضب الله لأنه منطلق ووقف ملاك الرب في الطريق ليقاومه وهو راكب على أتانه وغلاماه معه.","22:23":"فأبصرت الأتان ملاك الرب واقفا في الطريق وسيفه مسلول في يده فمالت الأتان عن الطريق ومشت في الحقل. فضرب بلعام الأتان ليردها إلى الطريق.","22:24":"ثم وقف ملاك الرب في خندق للكروم له حائط من هنا وحائط من هناك.","22:25":"فلما أبصرت الأتان ملاك الرب زحمت الحائط وضغطت رجل بلعام بالحائط فضربها أيضا.","22:26":"ثم اجتاز ملاك الرب أيضا ووقف في مكان ضيق حيث ليس سبيل للنكوب يمينا أو شمالا.","22:27":"فلما أبصرت الأتان ملاك الرب ربضت تحت بلعام. فحمي غضب بلعام وضرب الأتان بالقضيب.","22:28":"ففتح الرب فم الأتان فقالت لبلعام: «ماذا صنعت بك حتى ضربتني الآن ثلاث دفعات؟»","22:29":"فقال بلعام للأتان: «لأنك ازدريت بي. لو كان في يدي سيف لكنت الآن قد قتلتك».","22:30":"فقالت الأتان لبلعام: «ألست أنا أتانك التي ركبت عليها منذ وجودك إلى هذا اليوم؟ هل تعودت أن أفعل بك هكذا؟» فقال: «لا».","22:31":"ثم كشف الرب عن عيني بلعام فأبصر ملاك الرب واقفا في الطريق وسيفه مسلول في يده فخر ساجدا على وجهه.","22:32":"فقال له ملاك الرب: «لماذا ضربت أتانك الآن ثلاث دفعات؟ هئنذا قد خرجت للمقاومة لأن الطريق ورطة أمامي","22:33":"فأبصرتني الأتان ومالت من قدامي الآن ثلاث دفعات. ولو لم تمل من قدامي لكنت الآن قد قتلتك واستبقيتها».","22:34":"فقال بلعام لملاك الرب: «أخطأت. إني لم أعلم أنك واقف تلقائي في الطريق. والآن إن قبح في عينيك فإني أرجع».","22:35":"فقال ملاك الرب لبلعام: «اذهب مع الرجال وإنما تتكلم بالكلام الذي أكلمك به فقط». فانطلق بلعام مع رؤساء بالاق.","22:36":"فلما سمع بالاق أن بلعام جاء خرج لاستقباله إلى مدينة موآب التي على تخم أرنون الذي في أقصى التخوم.","22:37":"فقال بالاق لبلعام: «ألم أرسل إليك لأدعوك؟ لماذا لم تأت إلي؟ أحقا لا أقدر أن أكرمك؟»","22:38":"فقال بلعام لبالاق: «هئنذا قد جئت إليك. ألعلي الآن أستطيع أن أتكلم بشيء؟ الكلام الذي يضعه الله في فمي به أتكلم».","22:39":"فانطلق بلعام مع بالاق وأتيا إلى قرية حصوت.","22:40":"فذبح بالاق بقرا وغنما وأرسل إلى بلعام وإلى الرؤساء الذين معه.","22:41":"وفي الصباح أخذ بالاق بلعام وأصعده إلى مرتفعات بعل فرأى من هناك أقصى الشعب.","23:1":"فقال بلعام لبالاق: «ابن لي ههنا سبعة مذابح وهيئ لي ههنا سبعة ثيران وسبعة كباش».","23:2":"ففعل بالاق كما تكلم بلعام. وأصعد بالاق وبلعام ثورا وكبشا على كل مذبح.","23:3":"فقال بلعام لبالاق: «قف عند محرقتك فأنطلق أنا لعل الرب يوافي للقائي فمهما أراني أخبرك به». ثم انطلق إلى رابية.","23:4":"فوافى الله بلعام. فقال له: «قد رتبت سبعة مذابح وأصعدت ثورا وكبشا على كل مذبح».","23:5":"فوضع الرب كلاما في فم بلعام وقال: «ارجع إلى بالاق وتكلم هكذا».","23:6":"فرجع إليه وإذا هو واقف عند محرقته هو وجميع رؤساء موآب.","23:7":"فنطق بمثله وقال: «من أرام أتى بي بالاق ملك موآب من جبال المشرق. تعال العن لي يعقوب وهلم اشتم إسرائيل.","23:8":"كيف ألعن من لم يلعنه الله وكيف أشتم من لم يشتمه الرب؟","23:9":"إني من رأس الصخور أراه. ومن الآكام أبصره. هوذا شعب يسكن وحده. وبين الشعوب لا يحسب.","23:10":"من أحصى تراب يعقوب وربع إسرائيل بعدد؟ لتمت نفسي موت الأبرار ولتكن آخرتي كآخرتهم».","23:11":"فقال بالاق لبلعام: «ماذا فعلت بي؟ لتشتم أعدائي أخذتك وهوذا أنت قد باركتهم».","23:12":"فأجاب: «أما الذي يضعه الرب في فمي أحترص أن أتكلم به؟»","23:13":"فقال له بالاق: «هلم معي إلى مكان آخر تراه منه. إنما ترى أقصاءه فقط وكله لا ترى. فالعنه لي من هناك».","23:14":"فأخذه إلى حقل صوفيم إلى رأس الفسجة وبنى سبعة مذابح وأصعد ثورا وكبشا على كل مذبح.","23:15":"فقال لبالاق: «قف هنا عند محرقتك وأنا أوافي هناك».","23:16":"فوافى الرب بلعام ووضع كلاما في فمه وقال: «ارجع إلى بالاق وتكلم هكذا».","23:17":"فأتى إليه وإذا هو واقف عند محرقته ورؤساء موآب معه. فسأله بالاق: «ماذا تكلم به الرب؟»","23:18":"فنطق بمثله وقال: «قم يا بالاق واسمع. اصغ إلي يا ابن صفور.","23:19":"ليس الله إنسانا فيكذب ولا ابن إنسان فيندم. هل يقول ولا يفعل؟ أو يتكلم ولا يفي؟","23:20":"إني قد أمرت أن أبارك. فإنه قد بارك فلا أرده.","23:21":"لم يبصر إثما في يعقوب ولا رأى سوءا في إسرائيل. الرب إلهه معه. وهتاف ملك فيه.","23:22":"الله أخرجه من مصر. له مثل سرعة الرئم.","23:23":"إنه ليس عيافة على يعقوب ولا عرافة على إسرائيل. في الوقت يقال عن يعقوب وعن إسرائيل ما فعل الله.","23:24":"هوذا شعب يقوم كلبوة ويرتفع كأسد. لا ينام حتى يأكل فريسة ويشرب دم قتلى».","23:25":"فقال بالاق لبلعام: «لا تلعنه لعنة ولا تباركه بركة».","23:26":"فأجاب بلعام: «ألم أكلمك قائلا: كل ما يتكلم به الرب فإياه أفعل؟»","23:27":"فقال بالاق لبلعام: «هلم آخذك إلى مكان آخر؟ عسى أن يصلح في عيني الله أن تلعنه لي من هناك».","23:28":"فأخذ بالاق بلعام إلى رأس فغور المشرف على وجه البرية.","23:29":"فقال بلعام لبالاق: «ابن لي ههنا سبعة مذابح وهيئ لي ههنا سبعة ثيران وسبعة كباش».","23:30":"ففعل بالاق كما قال بلعام وأصعد ثورا وكبشا على كل مذبح.","24:1":"فلما رأى بلعام أنه يحسن في عيني الرب أن يبارك إسرائيل لم ينطلق كالمرة الأولى والثانية ليوافي فألا بل جعل نحو البرية وجهه.","24:2":"ورفع بلعام عينيه ورأى إسرائيل حالا حسب أسباطه فكان عليه روح الله","24:3":"فنطق بمثله وقال: «وحي بلعام بن بعور. وحي الرجل المفتوح العينين.","24:4":"وحي الذي يسمع أقوال الله. الذي يرى رؤيا القدير مطروحا وهو مكشوف العينين.","24:5":"ما أحسن خيامك يا يعقوب مساكنك يا إسرائيل!","24:6":"كأودية ممتدة. كجنات على نهر. كشجرات عود غرسها الرب. كأرزات على مياه.","24:7":"يجري ماء من دلائه ويكون زرعه على مياه غزيرة ويتسامى ملكه على أجاج وترتفع مملكته.","24:8":"الله أخرجه من مصر. له مثل سرعة الرئم. يأكل أمما مضايقيه. ويقضم عظامهم ويحطم سهامه.","24:9":"جثم كأسد. ربض كلبوة. من يقيمه! مباركك مبارك ولاعنك ملعون».","24:10":"فاشتعل غضب بالاق على بلعام وصفق بيديه وقال بالاق لبلعام: «لتشتم أعدائي دعوتك وهوذا أنت قد باركتهم الآن ثلاث دفعات.","24:11":"فالآن اهرب إلى مكانك. قلت أكرمك إكراما وهوذا الرب قد منعك عن الكرامة».","24:12":"فقال بلعام لبالاق: «ألم أكلم أيضا رسلك الذين أرسلت إلي قائلا:","24:13":"ولو أعطاني بالاق ملء بيته فضة وذهبا لا أقدر أن أتجاوز قول الرب لأعمل خيرا أو شرا من نفسي. الذي يتكلمه الرب إياه أتكلم.","24:14":"والآن هوذا أنا منطلق إلى شعبي. هلم أنبئك بما يفعله هذا الشعب بشعبك في آخر الأيام».","24:15":"ثم نطق بمثله وقال: «وحي بلعام بن بعور. وحي الرجل المفتوح العينين.","24:16":"وحي الذي يسمع أقوال الله ويعرف معرفة العلي. الذي يرى رؤيا القدير ساقطا وهو مكشوف العينين.","24:17":"أراه ولكن ليس الآن. أبصره ولكن ليس قريبا. يبرز كوكب من يعقوب ويقوم قضيب من إسرائيل فيحطم طرفي موآب ويهلك كل بني الوغى.","24:18":"ويكون أدوم ميراثا ويكون سعير أعداؤه ميراثا. ويصنع إسرائيل ببأس.","24:19":"ويتسلط الذي من يعقوب ويهلك الشارد من مدينة».","24:20":"ثم رأى عماليق فنطق بمثله وقال: «عماليق أول الشعوب وأما آخرته فإلى الهلاك».","24:21":"ثم رأى القيني فنطق بمثله وقال: «ليكن مسكنك متينا وعشك موضوعا في صخرة.","24:22":"لكن يكون قاين للدمار. حتى متى يستأسرك أشور؟»","24:23":"ثم نطق بمثله وقال: «آه! من يعيش حين يفعل ذلك.","24:24":"وتأتي سفن من ناحية كتيم وتخضع أشور وتخضع عابر فهو أيضا إلى الهلاك».","24:25":"ثم قام بلعام وانطلق ورجع إلى مكانه. وبالاق أيضا ذهب في طريقه.","25:1":"وأقام إسرائيل في شطيم وابتدأ الشعب يزنون مع بنات موآب.","25:2":"فدعون الشعب إلى ذبائح آلهتهن فأكل الشعب وسجدوا لآلهتهن.","25:3":"وتعلق إسرائيل ببعل فغور. فحمي غضب الرب على إسرائيل.","25:4":"فقال الرب لموسى: «خذ جميع رؤوس الشعب وعلقهم للرب مقابل الشمس فيرتد حمو غضب الرب عن إسرائيل».","25:5":"فقال موسى لقضاة إسرائيل: «اقتلوا كل واحد قومه المتعلقين ببعل فغور».","25:6":"وإذا رجل من بني إسرائيل جاء وقدم إلى إخوته المديانية أمام عيني موسى وأعين كل جماعة بني إسرائيل وهم باكون لدى باب خيمة الاجتماع.","25:7":"فلما رأى ذلك فينحاس بن ألعازار بن هارون الكاهن قام من وسط الجماعة وأخذ رمحا بيده","25:8":"ودخل وراء الرجل الإسرائيلي إلى القبة وطعن كليهما الرجل الإسرائيلي والمرأة في بطنها. فامتنع الوبأ عن بني إسرائيل.","25:9":"وكان الذين ماتوا بالوبإ أربعة وعشرين ألفا.","25:10":"فقال الرب لموسى:","25:11":"«فينحاس بن ألعازار بن هارون الكاهن قد رد سخطي عن بني إسرائيل بكونه غار غيرتي في وسطهم حتى لم أفن بني إسرائيل بغيرتي.","25:12":"لذلك قل هئنذا أعطيه ميثاقي ميثاق السلام","25:13":"فيكون له ولنسله من بعده ميثاق كهنوت أبدي لأجل أنه غار لله وكفر عن بني إسرائيل».","25:14":"وكان اسم الرجل الإسرائيلي الذي قتل مع المديانية زمري بن سالو رئيس بيت أب من الشمعونيين.","25:15":"واسم المرأة المديانية المقتولة كزبي بنت صور. هو رئيس قبائل بيت أب في مديان.","25:16":"ثم قال الرب لموسى:","25:17":"«ضايقوا المديانيين واضربوهم","25:18":"لأنهم ضايقوكم بمكايدهم التي كادوكم بها في أمر فغور وأمر كزبي أختهم بنت رئيس لمديان التي قتلت يوم الوبإ بسبب فغور».","26:1":"ثم بعد الوبإ أمر الرب موسى وألعازار بن هارون الكاهن:","26:2":"«خذا عدد كل جماعة بني إسرائيل من ابن عشرين سنة فصاعدا حسب بيوت آبائهم كل خارج للجند في إسرائيل».","26:3":"فقال موسى وألعازار الكاهن في عربات موآب على أردن أريحا:","26:4":"«من ابن عشرين سنة فصاعدا. كما أمر الرب موسى وبني إسرائيل الخارجين من أرض مصر:","26:5":"رأوبين بكر إسرائيل: بنو رأوبين. لحنوك عشيرة الحنوكيين. لفلو عشيرة الفلويين.","26:6":"لحصرون عشيرة الحصرونيين. لكرمي عشيرة الكرميين.","26:7":"هذه عشائر الرأوبينيين. وكان المعدودون منهم ثلاثة وأربعين ألفا وسبع مئة وثلاثين.","26:8":"وابن فلو أليآب.","26:9":"وبنو أليآب نموئيل وداثان وأبيرام وهما داثان وأبيرام المدعوان من الجماعة اللذان خاصما موسى وهارون في جماعة قورح حين خاصموا الرب","26:10":"ففتحت الأرض فاها وابتلعتهما مع قورح حين مات القوم بإحراق النار مئتين وخمسين رجلا. فصاروا عبرة.","26:11":"وأما بنو قورح فلم يموتوا.","26:12":"بنو شمعون حسب عشائرهم: لنموئيل عشيرة النموئيليين. ليامين عشيرة اليامينيين. لياكين عشيرة الياكينيين.","26:13":"لزارح عشيرة الزارحيين. لشأول عشيرة الشأوليين.","26:14":"هذه عشائر الشمعونيين اثنان وعشرون ألفا ومئتان.","26:15":"بنو جاد حسب عشائرهم: لصفون عشيرة الصفونيين. لحجي عشيرة الحجيين. لشوني عشيرة الشونيين.","26:16":"لأزني عشيرة الأزنيين. لعيري عشيرة العيريين","26:17":"لأرود عشيرة الأروديين. لأرئيلي عشيرة الأرئيليين.","26:18":"هذه عشائر بني جاد حسب عددهم أربعون ألفا وخمس مئة.","26:19":"ابنا يهوذا عير وأونان: ومات عير وأونان في أرض كنعان.","26:20":"فكان بنو يهوذا حسب عشائرهم: لشيلة عشيرة الشيليين. ولفارص عشيرة الفارصيين. ولزارح عشيرة الزارحيين.","26:21":"وكان بنو فارص: لحصرون عشيرة الحصرونيين. ولحامول عشيرة الحاموليين.","26:22":"هذه عشائر يهوذا حسب عددهم ستة وسبعون ألفا وخمس مئة.","26:23":"بنو يساكر حسب عشائرهم: لتولاع عشيرة التولاعيين. ولفوة عشيرة الفويين.","26:24":"ولياشوب عشيرة الياشوبيين. ولشمرون عشيرة الشمرونيين.","26:25":"هذه عشائر يساكر حسب عددهم أربعة وستون ألفا وثلاث مئة.","26:26":"بنو زبولون حسب عشائرهم: لسارد عشيرة السارديين. ولإيلون عشيرة الإيلونيين. ولياحلئيل عشيرة الياحلئيليين.","26:27":"هذه عشائر الزبولونيين حسب عددهم ستون ألفا وخمس مئة.","26:28":"ابنا يوسف حسب عشائرهما منسى وأفرايم:","26:29":"بنو منسى لماكير عشيرة الماكيريين. وماكير ولد جلعاد. ولجلعاد عشيرة الجلعاديين.","26:30":"هؤلاء بنو جلعاد. لإيعزر عشيرة الإيعزريين. لحالق عشيرة الحالقيين","26:31":"لأسريئيل عشيرة الأسريئيليين. لشكم عشيرة الشكميين","26:32":"لشميداع عشيرة الشميداعيين. لحافر عشيرة الحافريين.","26:33":"وأما صلفحاد بن حافر فلم يكن له بنون بل بنات. وأسماء بنات صلفحاد محلة ونوعة وحجلة وملكة وترصة.","26:34":"هذه عشائر منسى. والمعدودون منهم اثنان وخمسون ألفا وسبع مئة.","26:35":"وهؤلاء بنو أفرايم حسب عشائرهم: لشوتالح عشيرة الشوتالحيين. لباكر عشيرة الباكريين. لتاحن عشيرة التاحنيين.","26:36":"وهؤلاء بنو شوتالح. لعيران عشيرة العيرانيين.","26:37":"هذه عشائر بني أفرايم حسب عددهم اثنان وثلاثون ألفا وخمس مئة. هؤلاء بنو يوسف حسب عشائرهم.","26:38":"بنو بنيامين حسب عشائرهم. لبالع عشيرة البالعيين. لأشبيل عشيرة الأشبيليين. لأحيرام عشيرة الأحيراميين.","26:39":"لشفوفام عشيرة الشفوفاميين. لحوفام عشيرة الحوفاميين.","26:40":"وكان ابنا بالع: أرد ونعمان. لأرد عشيرة الأرديين ولنعمان عشيرة النعمانيين.","26:41":"هؤلاء بنو بنيامين حسب عشائرهم. والمعدودون منهم خمسة وأربعون ألفا وست مئة.","26:42":"هؤلاء بنو دان حسب عشائرهم: لشوحام عشيرة الشوحاميين. هذه قبائل دان حسب عشائرهم.","26:43":"جميع عشائر الشوحاميين حسب عددهم أربعة وستون ألفا وأربع مئة.","26:44":"بنو أشير حسب عشائرهم: ليمنة عشيرة اليمنيين. ليشوي عشيرة اليشويين. لبريعة عشيرة البريعيين.","26:45":"لبني بريعة لحابر عشيرة الحابريين. لملكيئيل عشيرة الملكيئيليين.","26:46":"واسم ابنة أشير سارح.","26:47":"هذه عشائر بني أشير حسب عددهم ثلاثة وخمسون ألفا وأربع مئة.","26:48":"بنو نفتالي حسب عشائرهم: لياحصئيل عشيرة الياحصئيليين. لجوني عشيرة الجونيين.","26:49":"ليصر عشيرة اليصريين. لشليم عشيرة الشليميين.","26:50":"هذه قبائل نفتالي حسب عشائرهم. والمعدودون منهم خمسة وأربعون ألفا وأربع مئة.","26:51":"هؤلاء المعدودون من بني إسرائيل ست مئة ألف وألف وسبع مئة وثلاثون.","26:52":"ثم أمر الرب موسى:","26:53":"«لهؤلاء تقسم الأرض نصيبا على عدد الأسماء.","26:54":"الكثير تكثر له نصيبه والقليل تقلل له نصيبه. كل واحد حسب المعدودين منه يعطى نصيبه.","26:55":"إنما بالقرعة تقسم الأرض. حسب أسماء أسباط آبائهم يملكون.","26:56":"حسب القرعة يقسم نصيبهم بين كثير وقليل».","26:57":"وهؤلاء المعدودون من اللاويين حسب عشائرهم: لجرشون عشيرة الجرشونيين. لقهات عشيرة القهاتيين. لمراري عشيرة المراريين.","26:58":"هذه عشائر لاوي. عشيرة اللبنيين وعشيرة الحبرونيين وعشيرة المحليين وعشيرة الموشيين وعشيرة القورحيين. وأما قهات فولد عمرام.","26:59":"واسم امرأة عمرام يوكابد بنت لاوي التي ولدت للاوي في مصر. فولدت لعمرام هارون وموسى ومريم أختهما.","26:60":"ولهارون ولد ناداب وأبيهو وألعازار وإيثامار.","26:61":"وأما ناداب وأبيهو فماتا عندما قربا نارا غريبة أمام الرب.","26:62":"وكان المعدودون منهم ثلاثة وعشرين ألفا كل ذكر من ابن شهر فصاعدا. لأنهم لم يعدوا بين بني إسرائيل إذ لم يعط لهم نصيب بين بني إسرائيل.","26:63":"هؤلاء هم الذين عدهم موسى وألعازار الكاهن حين عدا بني إسرائيل في عربات موآب على أردن أريحا.","26:64":"وفي هؤلاء لم يكن إنسان من الذين عدهم موسى وهارون الكاهن حين عدا بني إسرائيل في برية سيناء","26:65":"لأن الرب قال لهم إنهم يموتون في البرية فلم يبق منهم إنسان إلا كالب بن يفنة ويشوع بن نون.","27:1":"فتقدمت بنات صلفحاد بن حافر بن جلعاد بن ماكير بن منسى من عشائر منسى بن يوسف. وهذه أسماء بناته: محلة ونوعة وحجلة وملكة وترصة.","27:2":"ووقفن أمام موسى وألعازار الكاهن وأمام الرؤساء وكل الجماعة لدى باب خيمة الاجتماع قائلات:","27:3":"أبونا مات في البرية ولم يكن في القوم الذين اجتمعوا على الرب في جماعة قورح بل بخطيته مات ولم يكن له بنون.","27:4":"لماذا يحذف اسم أبينا من بين عشيرته لأنه ليس له ابن؟ أعطنا ملكا بين أعمامنا».","27:5":"فقدم موسى دعواهن أمام الرب.","27:6":"فقال الرب لموسى:","27:7":"«بحق تكلمت بنات صلفحاد فتعطيهن ملك نصيب بين أعمامهن وتنقل نصيب أبيهن إليهن.","27:8":"وتقول لبني إسرائيل: أيما رجل مات وليس له ابن تنقلون ملكه إلى ابنته.","27:9":"وإن لم تكن له ابنة تعطوا ملكه لإخوته.","27:10":"وإن لم يكن له إخوة تعطوا ملكه لأعمامه.","27:11":"وإن لم يكن لأبيه إخوة تعطوا ملكه لنسيبه الأقرب إليه من عشيرته فيرثه». فصارت لبني إسرائيل فريضة قضاء كما أمر الرب موسى.","27:12":"وقال الرب لموسى: «اصعد إلى جبل عباريم هذا وانظر الأرض التي أعطيت بني إسرائيل.","27:13":"ومتى نظرتها تضم إلى قومك أنت أيضا كما ضم هارون أخوك.","27:14":"لأنكما في برية صين عند مخاصمة الجماعة عصيتما قولي أن تقدساني بالماء أمام أعينهم». (ذلك ماء مريبة قادش في برية صين).","27:15":"فقال موسى للرب:","27:16":"«ليوكل الرب إله أرواح جميع البشر رجلا على الجماعة","27:17":"يخرج أمامهم ويدخل أمامهم ويخرجهم ويدخلهم لكيلا تكون جماعة الرب كالغنم التي لا راعي لها».","27:18":"فقال الرب لموسى: «خذ يشوع بن نون رجلا فيه روح وضع يدك عليه","27:19":"وأوقفه قدام ألعازار الكاهن وقدام كل الجماعة وأوصه أمام أعينهم.","27:20":"واجعل من هيبتك عليه ليسمع له كل جماعة بني إسرائيل","27:21":"فيقف أمام ألعازار الكاهن فيسأل له بقضاء الأوريم أمام الرب. حسب قوله يخرجون وحسب قوله يدخلون هو وكل بني إسرائيل معه كل الجماعة","27:22":"ففعل موسى كما أمره الرب. أخذ يشوع وأوقفه قدام ألعازار الكاهن وقدام كل الجماعة","27:23":"ووضع يديه عليه وأوصاه كما تكلم الرب عن يد موسى.","28:1":"وأمر الرب موسى:","28:2":"«أوص بني إسرائيل: قرباني طعامي مع وقائدي رائحة سروري تحرصون أن تقربوه لي في وقته.","28:3":"وقل لهم. هذا هو الوقود الذي تقربون للرب: خروفان حوليان صحيحان لكل يوم محرقة دائمة.","28:4":"الخروف الواحد تعمله صباحا والخروف الثاني تعمله بين العشاءين.","28:5":"وعشر الإيفة من دقيق ملتوت بربع الهين من زيت الرب تقدمة.","28:6":"محرقة دائمة. هي المعمولة في جبل سيناء. لرائحة سرور وقودا للرب.","28:7":"وسكيبها ربع الهين للخروف الواحد. في القدس اسكب سكيب مسكر للرب.","28:8":"والخروف الثاني تعمله بين العشاءين كتقدمة الصباح وكسكيبه تعمله وقود رائحة سرور للرب.","28:9":"«وفي يوم السبت خروفان حوليان صحيحان وعشران من دقيق ملتوت بزيت تقدمة مع سكيبه","28:10":"محرقة كل سبت فضلا عن المحرقة الدائمة وسكيبها.","28:11":"«وفي رؤوس شهوركم تقربون محرقة للرب: ثورين ابني بقر وكبشا واحدا وسبعة خراف حولية صحيحة","28:12":"وثلاثة أعشار من دقيق ملتوت بزيت تقدمة لكل ثور. وعشرين من دقيق ملتوت بزيت تقدمة للكبش الواحد.","28:13":"وعشرا واحدا من دقيق ملتوت بزيت تقدمة لكل خروف. محرقة رائحة سرور وقودا للرب.","28:14":"وسكائبهن تكون نصف الهين للثور وثلث الهين للكبش وربع الهين للخروف من خمر. هذه محرقة كل شهر من أشهر السنة.","28:15":"وتيسا واحدا من المعز ذبيحة خطية للرب. فضلا عن المحرقة الدائمة يقرب مع سكيبه.","28:16":"«وفي الشهر الأول في اليوم الرابع عشر من الشهر فصح للرب.","28:17":"وفي اليوم الخامس عشر من هذا الشهر عيد. سبعة أيام يؤكل فطير.","28:18":"في اليوم الأول محفل مقدس. عملا ما من الشغل لا تعملوا.","28:19":"وتقربون وقودا محرقة للرب ثورين ابني بقر وكبشا واحدا وسبعة خراف حولية. صحيحة تكون لكم.","28:20":"وتقدمتهن من دقيق ملتوت بزيت. ثلاثة أعشار تعملون للثور وعشرين للكبش","28:21":"وعشرا واحدا تعمل لكل خروف من السبعة الخراف","28:22":"وتيسا واحدا ذبيحة خطية للتكفير عنكم.","28:23":"فضلا عن محرقة الصباح التي لمحرقة دائمة تعملون هذه.","28:24":"هكذا تعملون كل يوم سبعة أيام طعام وقود رائحة سرور للرب. فضلا عن المحرقة الدائمة يعمل مع سكيبه.","28:25":"وفي اليوم السابع يكون لكم محفل مقدس. عملا ما من الشغل لا تعملوا.","28:26":"«وفي يوم الباكورة حين تقربون تقدمة جديدة للرب في أسابيعكم يكون لكم محفل مقدس. عملا ما من الشغل لا تعملوا.","28:27":"وتقربون محرقة لرائحة سرور للرب: ثورين ابني بقر وكبشا واحدا وسبعة خراف حولية.","28:28":"وتقدمتهن من دقيق ملتوت بزيت ثلاثة أعشار لكل ثور وعشرين للكبش الواحد","28:29":"وعشرا واحدا لكل خروف من السبعة الخراف","28:30":"وتيسا واحدا من المعز للتكفير عنكم.","28:31":"فضلا عن المحرقة الدائمة وتقدمتها تعملون. مع سكائبهن صحيحات تكون لكم».","29:1":"«وفي الشهر السابع في الأول من الشهر يكون لكم محفل مقدس. عملا ما من الشغل لا تعملوا. يوم هتاف بوق يكون لكم.","29:2":"وتعملون محرقة لرائحة سرور للرب ثورا واحدا ابن بقر وكبشا واحدا وسبعة خراف حولية صحيحة.","29:3":"وتقدمتهن من دقيق ملتوت بزيت ثلاثة أعشار للثور وعشرين للكبش.","29:4":"وعشرا واحدا لكل خروف من السبعة الخراف.","29:5":"وتيسا واحدا من المعز ذبيحة خطية للتكفير عنكم.","29:6":"فضلا عن محرقة الشهر وتقدمتها والمحرقة الدائمة وتقدمتها مع سكائبهن كعادتهن رائحة سرور وقودا للرب.","29:7":"«وفي عاشر هذا الشهر السابع يكون لكم محفل مقدس وتذللون أنفسكم. عملا ما لا تعملوا.","29:8":"وتقربون محرقة للرب رائحة سرور: ثورا واحدا ابن بقر وكبشا واحدا وسبعة خراف حولية. صحيحة تكون لكم.","29:9":"وتقدمتهن من دقيق ملتوت بزيت ثلاثة أعشار للثور وعشران للكبش الواحد","29:10":"وعشر واحد لكل خروف من السبعة الخراف.","29:11":"وتيسا واحدا من المعز ذبيحة خطية فضلا عن ذبيحة الخطية للكفارة والمحرقة الدائمة وتقدمتها مع سكائبهن.","29:12":"«وفي اليوم الخامس عشر من الشهر السابع يكون لكم محفل مقدس. عملا ما من الشغل لا تعملوا. وتعيدون عيدا للرب سبعة أيام.","29:13":"وتقربون محرقة وقود رائحة سرور للرب ثلاثة عشر ثورا أبناء بقر وكبشين وأربعة عشر خروفا حوليا. صحيحة تكون لكم.","29:14":"وتقدمتهن من دقيق ملتوت بزيت ثلاثة أعشار لكل ثور من الثلاثة عشر ثورا وعشران لكل كبش من الكبشين","29:15":"وعشر واحد لكل خروف من الأربعة عشر خروفا","29:16":"وتيسا واحدا من المعز ذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها وسكيبها.","29:17":"«وفي اليوم الثاني اثني عشر ثورا أبناء بقر وكبشين وأربعة عشر خروفا حوليا صحيحا.","29:18":"وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة.","29:19":"وتيسا واحدا من المعز ذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها مع سكائبهن.","29:20":"«وفي اليوم الثالث أحد عشر ثورا وكبشين وأربعة عشر خروفا حوليا صحيحا.","29:21":"وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة.","29:22":"وتيسا واحدا لذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها وسكيبها.","29:23":"«وفي اليوم الرابع عشرة ثيران وكبشين وأربعة عشر خروفا حوليا صحيحا.","29:24":"وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة.","29:25":"وتيسا واحدا من المعز لذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها وسكيبها.","29:26":"«وفي اليوم الخامس تسعة ثيران وكبشين وأربعة عشر خروفا حوليا صحيحا.","29:27":"وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة.","29:28":"وتيسا واحدا لذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها وسكيبها.","29:29":"«وفي اليوم السادس ثمانية ثيران وكبشين وأربعة عشر خروفا حوليا صحيحا.","29:30":"وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كالعادة.","29:31":"وتيسا واحدا لذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها وسكيبها.","29:32":"«وفي اليوم السابع سبعة ثيران وكبشين وأربعة عشر خروفا حوليا صحيحا.","29:33":"وتقدمتهن وسكائبهن للثيران والكبشين والخراف حسب عددهن كعادتهن.","29:34":"وتيسا واحدا لذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها وسكيبها.","29:35":"«في اليوم الثامن يكون لكم اعتكاف. عملا ما من الشغل لا تعملوا.","29:36":"وتقربون محرقة وقودا رائحة سرور للرب ثورا واحدا وكبشا واحدا وسبعة خراف حولية صحيحة.","29:37":"وتقدمتهن وسكائبهن للثور والكبش والخراف حسب عددهن كالعادة.","29:38":"وتيسا واحدا لذبيحة خطية فضلا عن المحرقة الدائمة وتقدمتها وسكيبها.","29:39":"هذه تقربونها للرب في مواسمكم فضلا عن نذوركم ونوافلكم من محرقاتكم وتقدماتكم وسكائبكم وذبائح سلامتكم».","29:40":"فكلم موسى بني إسرائيل حسب كل ما أمره به الرب.","30:1":"وقال موسى لرؤوس أسباط بني إسرائيل: «هذا ما أمر به الرب:","30:2":"إذا نذر رجل نذرا للرب أو أقسم قسما أن يلزم نفسه بلازم فلا ينقض كلامه. حسب كل ما خرج من فمه يفعل.","30:3":"وأما المرأة فإذا نذرت نذرا للرب والتزمت بلازم في بيت أبيها في صباها","30:4":"وسمع أبوها نذرها واللازم الذي ألزمت نفسها به فإن سكت أبوها لها ثبتت كل نذورها. وكل لوازمها التي ألزمت نفسها بها تثبت.","30:5":"وإن نهاها أبوها يوم سمعه فكل نذورها ولوازمها التي ألزمت نفسها بها لا تثبت والرب يصفح عنها لأن أباها قد نهاها.","30:6":"وإن كانت لزوج ونذورها عليها أو نطق شفتيها الذي ألزمت نفسها به","30:7":"وسمع زوجها فإن سكت في يوم سمعه ثبتت نذورها. ولوازمها التي ألزمت نفسها بها تثبت.","30:8":"وإن نهاها رجلها في يوم سمعه فسخ نذرها الذي عليها ونطق شفتيها الذي ألزمت نفسها به والرب يصفح عنها.","30:9":"وأما نذر أرملة أو مطلقة فكل ما ألزمت نفسها به يثبت عليها.","30:10":"ولكن إن نذرت في بيت زوجها أو ألزمت نفسها بلازم بقسم","30:11":"وسمع زوجها فإن سكت لها ولم ينهها ثبتت كل نذورها. وكل لازم ألزمت نفسها به يثبت.","30:12":"وإن فسخها زوجها في يوم سمعه فكل ما خرج من شفتيها من نذورها أو لوازم نفسها لا يثبت. قد فسخها زوجها. والرب يصفح عنها.","30:13":"كل نذر وكل قسم التزام لإذلال النفس زوجها يثبته وزوجها يفسخه.","30:14":"وإن سكت لها زوجها من يوم إلى يوم فقد أثبت كل نذورها أو كل لوازمها التي عليها. أثبتها لأنه سكت لها في يوم سمعه.","30:15":"فإن فسخها بعد سمعه فقد حمل ذنبها».","30:16":"هذه هي الفرائض التي أمر بها الرب موسى بين الزوج وزوجته وبين الأب وابنته في صباها في بيت أبيها.","31:1":"وأمر الرب موسى:","31:2":"«انتقم نقمة لبني إسرائيل من المديانيين ثم تضم إلى قومك».","31:3":"فقال موسى للشعب: «جردوا منكم رجالا للجند فيكونوا على مديان ليجعلوا نقمة الرب على مديان.","31:4":"ألفا واحدا من كل سبط من جميع أسباط إسرائيل ترسلون للحرب».","31:5":"فاختير من ألوف إسرائيل ألف من كل سبط. اثنا عشر ألفا مجردون للحرب.","31:6":"فأرسلهم موسى ألفا من كل سبط إلى الحرب هم وفينحاس بن ألعازار الكاهن إلى الحرب وأمتعة القدس وأبواق الهتاف في يده.","31:7":"فتجندوا على مديان كما أمر الرب وقتلوا كل ذكر.","31:8":"وملوك مديان قتلوهم فوق قتلاهم. أوي وراقم وصور وحور ورابع. خمسة ملوك مديان. وبلعام بن بعور قتلوه بالسيف.","31:9":"وسبى بنو إسرائيل نساء مديان وأطفالهم ونهبوا جميع بهائمهم وجميع مواشيهم وكل أملاكهم.","31:10":"وأحرقوا جميع مدنهم بمساكنهم وجميع حصونهم بالنار.","31:11":"وأخذوا كل الغنيمة وكل النهب من الناس والبهائم","31:12":"وأتوا إلى موسى وألعازار الكاهن وإلى جماعة بني إسرائيل بالسبي والنهب والغنيمة إلى المحلة إلى عربات موآب التي على أردن أريحا.","31:13":"فخرج موسى وألعازار الكاهن وكل رؤساء الجماعة لاستقبالهم إلى خارج المحلة.","31:14":"فسخط موسى على وكلاء الجيش رؤساء الألوف ورؤساء المئات القادمين من جند الحرب.","31:15":"وقال لهم موسى: «هل أبقيتم كل أنثى حية؟","31:16":"إن هؤلاء كن لبني إسرائيل حسب كلام بلعام سبب خيانة للرب في أمر فغور فكان الوبأ في جماعة الرب.","31:17":"فالآن اقتلوا كل ذكر من الأطفال. وكل امرأة عرفت رجلا بمضاجعة ذكر اقتلوها.","31:18":"لكن جميع الأطفال من النساء اللواتي لم يعرفن مضاجعة ذكر أبقوهن لكم حيات.","31:19":"وأما أنتم فانزلوا خارج المحلة سبعة أيام. وتطهروا كل من قتل نفسا وكل من مس قتيلا في اليوم الثالث وفي السابع أنتم وسبيكم.","31:20":"وكل ثوب وكل متاع من جلد وكل مصنوع من شعر معز وكل متاع من خشب تطهرونه».","31:21":"وقال ألعازار الكاهن لرجال الجند الذين ذهبوا للحرب: «هذه فريضة الشريعة التي أمر بها الرب موسى.","31:22":"الذهب والفضة والنحاس والحديد والقصدير والرصاص","31:23":"كل ما يدخل النار تجيزونه في النار فيكون طاهرا غير أنه يتطهر بماء النجاسة. وأما كل ما لا يدخل النار فتجيزونه في الماء.","31:24":"وتغسلون ثيابكم في اليوم السابع فتكونون طاهرين وبعد ذلك تدخلون المحلة».","31:25":"وقال الرب لموسى:","31:26":"«أحص النهب المسبي من الناس والبهائم أنت وألعازار الكاهن ورؤوس آباء الجماعة.","31:27":"ونصف النهب بين الذين باشروا القتال الخارجين إلى الحرب وبين كل الجماعة.","31:28":"وارفع زكاة للرب. من رجال الحرب الخارجين إلى القتال واحدة. نفسا من كل خمس مئة من الناس والبقر والحمير والغنم.","31:29":"من نصفهم تأخذونها وتعطونها لألعازار الكاهن رفيعة للرب.","31:30":"ومن نصف بني إسرائيل تأخذ واحدة مأخوذة من كل خمسين من الناس والبقر والحمير والغنم من جميع البهائم وتعطيها للاويين الحافظين شعائر مسكن الرب».","31:31":"ففعل موسى وألعازار الكاهن كما أمر الرب موسى.","31:32":"وكان النهب فضلة الغنيمة التي اغتنمها رجال الجند من الغنم ست مئة وخمسة وسبعين ألفا.","31:33":"ومن البقر اثنين وسبعين ألفا.","31:34":"ومن الحمير واحدا وستين ألفا.","31:35":"ومن نفوس الناس من النساء اللواتي لم يعرفن مضاجعة ذكر جميع النفوس اثنين وثلاثين ألفا.","31:36":"وكان النصف نصيب الخارجين إلى الحرب: عدد الغنم ثلاث مئة وسبعة وثلاثين ألفا وخمس مئة.","31:37":"وكانت الزكاة للرب من الغنم ست مئة وخمسة وسبعين.","31:38":"والبقر ستة وثلاثين ألفا وزكاتها للرب اثنين وسبعين.","31:39":"والحمير ثلاثين ألفا وخمس مئة وزكاتها للرب واحدا وستين.","31:40":"ونفوس الناس ستة عشر ألفا وزكاتها للرب اثنين وثلاثين نفسا.","31:41":"فأعطى موسى الزكاة رفيعة الرب لألعازار الكاهن كما أمر الرب موسى.","31:42":"وأما نصف إسرائيل الذي قسمه موسى من الرجال المتجندين","31:43":"فكان نصف الجماعة من الغنم ثلاث مئة وسبعة وثلاثين ألفا وخمس مئة.","31:44":"ومن البقر ستة وثلاثين ألفا.","31:45":"ومن الحمير ثلاثين ألفا وخمس مئة.","31:46":"ومن نفوس الناس ستة عشر ألفا.","31:47":"فأخذ موسى من نصف بني إسرائيل المأخوذ واحدا من كل خمسين من الناس ومن البهائم وأعطاها للاويين الحافظين شعائر مسكن الرب كما أمر الرب موسى.","31:48":"ثم تقدم إلى موسى الوكلاء الذين على ألوف الجند رؤساء الألوف ورؤساء المئات","31:49":"وقالوا لموسى: «عبيدك قد أخذوا عدد رجال الحرب الذين في أيدينا فلم يفقد منا إنسان.","31:50":"فقد قدمنا قربان الرب كل واحد ما وجده أمتعة ذهب حجولا وأساور وخواتم وأقراطا وقلائد للتكفير عن أنفسنا أمام الرب».","31:51":"فأخذ موسى وألعازار الكاهن الذهب منهم كل أمتعة مصنوعة.","31:52":"وكان كل ذهب الرفيعة التي رفعوها للرب ستة عشر ألفا وسبع مئة وخمسين شاقلا من عند رؤساء الألوف ورؤساء المئات.","31:53":"(أما رجال الجند فاغتنموا كل واحد لنفسه).","31:54":"فأخذ موسى وألعازار الكاهن الذهب من رؤساء الألوف والمئات وأتيا به إلى خيمة الاجتماع تذكارا لبني إسرائيل أمام الرب.","32:1":"وأما بنو رأوبين وبنو جاد فكان لهم مواش كثيرة وافرة جدا. فلما رأوا أرض يعزير وأرض جلعاد وإذا المكان مكان مواش","32:2":"أتى بنو جاد وبنو رأوبين وقالوا لموسى وألعازار الكاهن ورؤساء الجماعة:","32:3":"«عطاروت وديبون ويعزير ونمرة وحشبون وألعالة وشبام ونبو وبعون","32:4":"الأرض التي ضربها الرب قدام بني إسرائيل هي أرض مواش ولعبيدك مواش».","32:5":"ثم قالوا: «إن وجدنا نعمة في عينيك فلتعط هذه الأرض لعبيدك ملكا ولا تعبرنا الأردن».","32:6":"فقال موسى لبني جاد وبني رأوبين: «هل ينطلق إخوتكم إلى الحرب وأنتم تقعدون ههنا؟","32:7":"فلماذا تصدون قلوب بني إسرائيل عن العبور إلى الأرض التي أعطاهم الرب؟","32:8":"هكذا فعل آباؤكم حين أرسلتهم من قادش برنيع لينظروا الأرض.","32:9":"صعدوا إلى وادي أشكول ونظروا الأرض وصدوا قلوب بني إسرائيل عن دخول الأرض التي أعطاهم الرب.","32:10":"فحمي غضب الرب في ذلك اليوم وأقسم قائلا:","32:11":"لن يرى الناس الذين صعدوا من مصر من ابن عشرين سنة فصاعدا الأرض التي أقسمت لإبراهيم وإسحاق ويعقوب لأنهم لم يتبعوني تماما","32:12":"ما عدا كالب بن يفنة القنزي ويشوع بن نون لأنهما اتبعا الرب تماما.","32:13":"فحمي غضب الرب على إسرائيل وأتاههم في البرية أربعين سنة حتى فني كل الجيل الذي فعل الشر في عيني الرب.","32:14":"فهوذا أنتم قد قمتم عوضا عن آبائكم تربية أناس خطاة لتزيدوا أيضا حمو غضب الرب على إسرائيل.","32:15":"إذا ارتددتم من ورائه يعود يتركه أيضا في البرية فتهلكون كل هذا الشعب».","32:16":"فاقتربوا إليه وقالوا: «نبني حظائر غنم لمواشينا ههنا ومدنا لأطفالنا.","32:17":"وأما نحن فنتجرد مسرعين قدام بني إسرائيل حتى نأتي بهم إلى مكانهم. ويلبث أطفالنا في مدن محصنة من وجه سكان الأرض.","32:18":"لا نرجع إلى بيوتنا حتى يقتسم بنو إسرائيل كل واحد نصيبه.","32:19":"إننا لا نملك معهم في عبر الأردن وما وراءه لأن نصيبنا قد حصل لنا في عبر الأردن إلى الشرق».","32:20":"فقال لهم موسى: «إن فعلتم هذا الأمر إن تجردتم أمام الرب للحرب","32:21":"وعبر الأردن كل متجرد منكم أمام الرب حتى طرد أعداءه من أمامه","32:22":"وأخضعت الأرض أمام الرب وبعد ذلك رجعتم فتكونون أبرياء من نحو الرب ومن نحو إسرائيل وتكون هذه الأرض ملكا لكم أمام الرب.","32:23":"ولكن إن لم تفعلوا هكذا فإنكم تخطئون إلى الرب. وتعلمون خطيتكم التي تصيبكم.","32:24":"ابنوا لأنفسكم مدنا لأطفالكم وحظائر لغنمكم. وما خرج من أفواهكم افعلوا».","32:25":"فقال بنو جاد وبنو رأوبين لموسى: «عبيدك يفعلون كما أمر سيدي.","32:26":"أطفالنا ونساؤنا ومواشينا وكل بهائمنا تكون هناك في مدن جلعاد.","32:27":"وعبيدك يعبرون كل متجرد للجند أمام الرب للحرب كما تكلم سيدي».","32:28":"فأوصى بهم موسى ألعازار الكاهن ويشوع بن نون ورؤوس آباء الأسباط من بني إسرائيل.","32:29":"وقال لهم موسى: «إن عبر الأردن معكم بنو جاد وبنو رأوبين كل متجرد للحرب أمام الرب فمتى أخضعت الأرض أمامكم تعطونهم أرض جلعاد ملكا.","32:30":"ولكن إن لم يعبروا متجردين معكم يتملكوا في وسطكم في أرض كنعان».","32:31":"فأجاب بنو جاد وبنو رأوبين: «الذي تكلم به الرب عن عبيدك كذلك نفعل.","32:32":"نحن نعبر متجردين أمام الرب إلى أرض كنعان ولكن نعطى ملك نصيبنا في عبر الأردن».","32:33":"فأعطى موسى لهم لبني جاد وبني رأوبين ونصف سبط منسى بن يوسف مملكة سيحون ملك الأموريين ومملكة عوج ملك باشان الأرض مع مدنها بتخوم مدن الأرض حواليها.","32:34":"فبنى بنو جاد ديبون وعطاروت وعروعير","32:35":"وعطروت شوفان ويعزير ويجبهة","32:36":"وبيت نمرة وبيت هاران مدنا محصنة مع حظائر غنم.","32:37":"وبنى بنو رأوبين حشبون وألعالة وقريتايم","32:38":"ونبو وبعل معون (مغيرتي الاسم) وسبمة ودعوا بأسماء أسماء المدن التي بنوا.","32:39":"وذهب بنو ماكير بن منسى إلى جلعاد وأخذوها وطردوا الأموريين الذين فيها.","32:40":"فأعطى موسى جلعاد لماكير بن منسى فسكن فيها.","32:41":"وذهب يائير ابن منسى وأخذ مزارعها ودعاهن حووث يائير.","32:42":"وذهب نوبح وأخذ قناة وقراها ودعاها نوبح باسمه.","33:1":"هذه رحلات بني إسرائيل الذين خرجوا من أرض مصر بجنودهم عن يد موسى وهارون.","33:2":"وكتب موسى مخارجهم برحلاتهم حسب قول الرب. وهذه رحلاتهم بمخارجهم:","33:3":"ارتحلوا من رعمسيس في الشهر الأول في اليوم الخامس عشر من الشهر الأول في غد الفصح. خرج بنو إسرائيل بيد رفيعة أمام أعين جميع المصريين","33:4":"إذ كان المصريون يدفنون الذين ضرب منهم الرب من كل بكر. والرب قد صنع بآلهتهم أحكاما.","33:5":"فارتحل بنو إسرائيل من رعمسيس ونزلوا في سكوت.","33:6":"ثم ارتحلوا من سكوت ونزلوا في إيثام التي في طرف البرية.","33:7":"ثم ارتحلوا من إيثام ورجعوا على فم الحيروث التي قبالة بعل صفون ونزلوا أمام مجدل.","33:8":"ثم ارتحلوا من أمام الحيروث وعبروا في وسط البحر إلى البرية وساروا مسيرة ثلاثة أيام في برية إيثام ونزلوا في مارة.","33:9":"ثم ارتحلوا من مارة وأتوا إلى إيليم. وكان في إيليم اثنتا عشرة عين ماء وسبعون نخلة. فنزلوا هناك.","33:10":"ثم ارتحلوا من إيليم ونزلوا على بحر سوف.","33:11":"ثم ارتحلوا من بحر سوف ونزلوا في برية سين.","33:12":"ثم ارتحلوا من برية سين ونزلوا في دفقة.","33:13":"ثم ارتحلوا من دفقة ونزلوا في ألوش.","33:14":"ثم ارتحلوا من ألوش ونزلوا في رفيديم. ولم يكن هناك ماء للشعب ليشرب.","33:15":"ثم ارتحلوا من رفيديم ونزلوا في برية سيناء.","33:16":"ثم ارتحلوا من برية سيناء ونزلوا في قبروت هتأوة.","33:17":"ثم ارتحلوا من قبروت هتأوة ونزلوا في حضيروت.","33:18":"ثم ارتحلوا من حضيروت ونزلوا في رثمة.","33:19":"ثم ارتحلوا من رثمة ونزلوا في رمون فارص.","33:20":"ثم ارتحلوا من رمون فارص ونزلوا في لبنة.","33:21":"ثم ارتحلوا من لبنة ونزلوا في رسة.","33:22":"ثم ارتحلوا من رسة ونزلوا في قهيلاتة.","33:23":"ثم ارتحلوا من قهيلاتة ونزلوا في جبل شافر.","33:24":"ثم ارتحلوا من جبل شافر ونزلوا في حرادة.","33:25":"ثم ارتحلوا من حرادة ونزلوا في مقهيلوت.","33:26":"ثم ارتحلوا من مقهيلوت ونزلوا في تاحت.","33:27":"ثم ارتحلوا من تاحت ونزلوا في تارح.","33:28":"ثم ارتحلوا من تارح ونزلوا في مثقة.","33:29":"ثم ارتحلوا من مثقة ونزلوا في حشمونة.","33:30":"ثم ارتحلوا من حشمونة ونزلوا في مسيروت.","33:31":"ثم ارتحلوا من مسيروت ونزلوا في بني يعقان.","33:32":"ثم ارتحلوا من بني يعقان ونزلوا في حور الجدجاد.","33:33":"ثم ارتحلوا من حور الجدجاد ونزلوا في يطبات.","33:34":"ثم ارتحلوا من يطبات ونزلوا في عبرونة.","33:35":"ثم ارتحلوا من عبرونة ونزلوا في عصيون جابر.","33:36":"ثم ارتحلوا من عصيون جابر ونزلوا في برية صين (وهي قادش).","33:37":"ثم ارتحلوا من قادش ونزلوا في جبل هور في طرف أرض أدوم.","33:38":"فصعد هارون الكاهن إلى جبل هور حسب قول الرب ومات هناك في السنة الأربعين لخروج بني إسرائيل من أرض مصر في الشهر الخامس في الأول من الشهر.","33:39":"وكان هارون ابن مئة وثلاث وعشرين سنة حين مات في جبل هور.","33:40":"وسمع الكنعاني ملك عراد وهو ساكن في الجنوب في أرض كنعان بمجيء بني إسرائيل.","33:41":"ثم ارتحلوا من جبل هور ونزلوا في صلمونة.","33:42":"ثم ارتحلوا من صلمونة ونزلوا في فونون.","33:43":"ثم ارتحلوا من فونون ونزلوا في أوبوت.","33:44":"ثم ارتحلوا من أوبوت ونزلوا في عيي عباريم في تخم موآب.","33:45":"ثم ارتحلوا من عييم ونزلوا في ديبون جاد.","33:46":"ثم ارتحلوا من ديبون جاد ونزلوا في علمون دبلاتايم.","33:47":"ثم ارتحلوا من علمون دبلاتايم ونزلوا في جبال عباريم أمام نبو.","33:48":"ثم ارتحلوا من جبال عباريم ونزلوا في عربات موآب على أردن أريحا.","33:49":"نزلوا على الأردن من بيت يشيموت إلى آبل شطيم في عربات موآب.","33:50":"وقال الرب لموسى في عربات موآب على أردن أريحا:","33:51":"«قل لبني إسرائيل: إنكم عابرون الأردن إلى أرض كنعان","33:52":"فتطردون كل سكان الأرض من أمامكم وتمحون جميع تصاويرهم وتبيدون كل أصنامهم المسبوكة وتخربون جميع مرتفعاتهم.","33:53":"تملكون الأرض وتسكنون فيها لأني قد أعطيتكم الأرض لكي تملكوها","33:54":"وتقتسمون الأرض بالقرعة حسب عشائركم. الكثير تكثرون له نصيبه والقليل تقللون له نصيبه. حيث خرجت له القرعة فهناك يكون له. حسب أسباط آبائكم تقتسمون.","33:55":"وإن لم تطردوا سكان الأرض من أمامكم يكون الذين تستبقون منهم أشواكا في أعينكم ومناخس في جوانبكم ويضايقونكم على الأرض التي أنتم ساكنون فيها.","33:56":"فيكون أني أفعل بكم كما هممت أن أفعل بهم».","34:1":"وأمر الرب موسى:","34:2":"«قل لبني إسرائيل: إنكم داخلون إلى أرض كنعان. هذه هي الأرض التي تقع لكم نصيبا. أرض كنعان بتخومها.","34:3":"تكون لكم ناحية الجنوب من برية صين على جانب أدوم. ويكون لكم تخم الجنوب من طرف بحر الملح إلى الشرق","34:4":"ويدور لكم التخم من جنوب عقبة عقربيم ويعبر إلى صين وتكون مخارجه من جنوب قادش برنيع ويخرج إلى حصر أدار ويعبر إلى عصمون.","34:5":"ثم يدور التخم من عصمون إلى وادي مصر وتكون مخارجه عند البحر.","34:6":"وأما تخم الغرب فيكون البحر الكبير لكم تخما. هذا يكون لكم تخم الغرب.","34:7":"وهذا يكون لكم تخم الشمال. من البحر الكبير ترسمون لكم إلى جبل هور.","34:8":"ومن جبل هور ترسمون إلى مدخل حماة وتكون مخارج التخم إلى صدد.","34:9":"ثم يخرج التخم إلى زفرون وتكون مخارجه عند حصر عينان. هذا يكون لكم تخم الشمال.","34:10":"وترسمون لكم تخما إلى الشرق من حصر عينان إلى شفام.","34:11":"وينحدر التخم من شفام إلى ربلة شرقي عين. ثم ينحدر التخم ويمس جانب بحر كنارة إلى الشرق.","34:12":"ثم ينحدر التخم إلى الأردن وتكون مخارجه عند بحر الملح. هذه تكون لكم الأرض بتخومها حواليها».","34:13":"فأمر موسى بني إسرائيل: «هذه هي الأرض التي تقتسمونها بالقرعة التي أمر الرب أن تعطى للتسعة الأسباط ونصف السبط.","34:14":"لأنه قد أخذ سبط بني رأوبين حسب بيوت آبائهم وسبط بني جاد حسب بيوت آبائهم ونصف سبط منسى. قد أخذوا نصيبهم.","34:15":"السبطان ونصف السبط قد أخذوا نصيبهم في عبر أردن أريحا شرقا نحو الشروق».","34:16":"وقال الرب لموسى:","34:17":"«هذان اسما الرجلين اللذين يقسمان لكم الأرض: ألعازار الكاهن ويشوع بن نون.","34:18":"ورئيسا واحدا من كل سبط تأخذون لقسمة الأرض.","34:19":"وهذه أسماء الرجال. من سبط يهوذا كالب بن يفنة.","34:20":"ومن سبط بني شمعون شموئيل بن عميهود.","34:21":"ومن سبط بنيامين أليداد بن كسلون.","34:22":"ومن سبط بني دان الرئيس بقي بن يجلي.","34:23":"ومن بني يوسف: من سبط بني منسى الرئيس حنيئيل بن إيفود.","34:24":"ومن سبط بني أفرايم الرئيس قموئيل بن شفطان.","34:25":"ومن سبط بني زبولون الرئيس أليصافان بن فرناخ.","34:26":"ومن سبط بني يساكر الرئيس فلطيئيل بن عزان.","34:27":"ومن سبط بني أشير الرئيس أخيهود بن شلومي.","34:28":"ومن سبط بني نفتالي الرئيس فدهئيل بن عميهود».","34:29":"هؤلاء هم الذين أمرهم الرب أن يقسموا لبني إسرائيل في أرض كنعان.","35:1":"ثم أمر الرب موسى في عربات موآب على أردن أريحا:","35:2":"«أوص بني إسرائيل أن يعطوا اللاويين من نصيب ملكهم مدنا للسكن ومراعي للمدن حواليها تعطون اللاويين.","35:3":"فتكون المدن لهم للسكن ومراعيها لبهائمهم وأموالهم ولسائر حيواناتهم.","35:4":"ومراعي المدن التي تعطون اللاويين تكون من سور المدينة إلى جهة الخارج ألف ذراع حواليها.","35:5":"فتقيسون من خارج المدينة جانب الشرق ألفي ذراع وجانب الجنوب ألفي ذراع وجانب الغرب ألفي ذراع وجانب الشمال ألفي ذراع وتكون المدينة في الوسط. هذه تكون لهم مراعي المدن.","35:6":"والمدن التي تعطون اللاويين تكون ست منها مدنا للملجإ. تعطونها لكي يهرب إليها القاتل. وفوقها تعطون اثنتين وأربعين مدينة.","35:7":"جميع المدن التي تعطون اللاويين ثماني وأربعون مدينة مع مراعيها.","35:8":"والمدن التي تعطون من ملك بني إسرائيل من الكثير تكثرون ومن القليل تقللون. كل واحد حسب نصيبه الذي ملكه يعطي من مدنه للاويين».","35:9":"وأمر الرب موسى:","35:10":"«قل لبني إسرائيل: إنكم عابرون الأردن إلى أرض كنعان.","35:11":"فتعينون لأنفسكم مدنا تكون مدن ملجأ لكم ليهرب إليها القاتل الذي قتل نفسا سهوا.","35:12":"فتكون لكم المدن ملجأ من الولي لكيلا يموت القاتل حتى يقف أمام الجماعة للقضاء.","35:13":"والمدن التي تعطون تكون ست مدن ملجأ لكم.","35:14":"ثلاثا من المدن تعطون في عبر الأردن وثلاثا من المدن تعطون في أرض كنعان. مدن ملجأ تكون","35:15":"لبني إسرائيل وللغريب وللمستوطن في وسطهم تكون هذه الست المدن للملجإ لكي يهرب إليها كل من قتل نفسا سهوا.","35:16":"«إن ضربه بأداة حديد فمات فهو قاتل. إن القاتل يقتل.","35:17":"وإن ضربه بحجر يد مما يقتل به فمات فهو قاتل. إن القاتل يقتل.","35:18":"أو ضربه بأداة يد من خشب مما يقتل به فهو قاتل. إن القاتل يقتل.","35:19":"ولي الدم يقتل القاتل. حين يصادفه يقتله.","35:20":"وإن دفعه ببغضة أو ألقى عليه شيئا بتعمد فمات","35:21":"أو ضربه بيده بعداوة فمات فإنه يقتل الضارب لأنه قاتل. ولي الدم يقتل القاتل حين يصادفه.","35:22":"ولكن إن دفعه بغتة بلا عداوة أو ألقى عليه أداة ما بلا تعمد","35:23":"أو حجرا ما مما يقتل به بلا رؤية. أسقطه عليه فمات وهو ليس عدوا له ولا طالبا أذيته","35:24":"تقضي الجماعة بين القاتل وبين ولي الدم حسب هذه الأحكام.","35:25":"وتنقذ الجماعة القاتل من يد ولي الدم وترده الجماعة إلى مدينة ملجئه التي هرب إليها فيقيم هناك إلى موت الكاهن العظيم الذي مسح بالدهن المقدس.","35:26":"ولكن إن خرج القاتل من حدود مدينة ملجئه التي هرب إليها","35:27":"ووجده ولي الدم خارج حدود مدينة ملجئه وقتل ولي الدم القاتل فليس له دم","35:28":"لأنه في مدينة ملجئه يقيم إلى موت الكاهن العظيم. وأما بعد موت الكاهن العظيم فيرجع القاتل إلى أرض ملكه.","35:29":"«فتكون هذه لكم فريضة حكم إلى أجيالكم في جميع مساكنكم.","35:30":"كل من قتل نفسا فعلى فم شهود يقتل القاتل. وشاهد واحد لا يشهد على نفس للموت.","35:31":"ولا تأخذوا فدية عن نفس القاتل المذنب للموت بل إنه يقتل.","35:32":"ولا تأخذوا فدية ليهرب إلى مدينة ملجئه فيرجع ويسكن في الأرض بعد موت الكاهن.","35:33":"لا تدنسوا الأرض التي أنتم فيها لأن الدم يدنس الأرض. وعن الأرض لا يكفر لأجل الدم الذي سفك فيها إلا بدم سافكه.","35:34":"ولا تنجسوا الأرض التي أنتم مقيمون فيها التي أنا ساكن في وسطها. إني أنا الرب ساكن في وسط بني إسرائيل».","36:1":"وتقدم رؤوس الآباء من عشيرة بني جلعاد بن ماكير بن منسى من عشائر بني يوسف: وتكلموا قدام موسى وقدام رؤساء الآباء من بني إسرائيل","36:2":"وقالوا: «قد أمر الرب سيدي أن يعطي الأرض بقسمة بالقرعة لبني إسرائيل. وقد أمر الرب سيدي أن يعطي نصيب صلفحاد أخينا لبناته.","36:3":"فإن صرن نساء لأحد من بني أسباط بني إسرائيل يؤخذ نصيبهن من نصيب آبائنا ويضاف إلى نصيب السبط الذي صرن له. فمن قرعة نصيبنا يؤخذ.","36:4":"ومتى كان اليوبيل لبني إسرائيل يضاف نصيبهن إلى نصيب السبط الذي صرن له ومن نصيب سبط آبائنا يؤخذ نصيبهن».","36:5":"فأمر موسى بني إسرائيل حسب قول الرب: «بحق تكلم سبط بني يوسف.","36:6":"هذا ما أمر به الرب عن بنات صلفحاد: من حسن في أعينهن يكن له نساء ولكن لعشيرة سبط آبائهن يكن نساء.","36:7":"فلا يتحول نصيب لبني إسرائيل من سبط إلى سبط بل يلازم بنو إسرائيل كل واحد نصيب سبط آبائه.","36:8":"وكل بنت ورثت نصيبا من أسباط بني إسرائيل تكون امرأة لواحد من عشيرة سبط أبيها ليرث بنو إسرائيل كل واحد نصيب آبائه","36:9":"فلا يتحول نصيب من سبط إلى سبط آخر بل يلازم أسباط بني إسرائيل كل واحد نصيبه».","36:10":"كما أمر الرب موسى كذلك فعلت بنات صلفحاد.","36:11":"فصارت محلة وترصة وحجلة وملكة ونوعة بنات صلفحاد نساء لبني أعمامهن.","36:12":"صرن نساء من عشائر بني منسى بن يوسف فبقي نصيبهن في سبط عشيرة أبيهن.","36:13":"هذه هي الوصايا والأحكام التي أوصى بها الرب إلى بني إسرائيل عن يد موسى في عربات موآب على أردن أريحا."};
